-- Evidence-based fræðsla: 16 slide lectures (4 per pillar), researched and
-- proofread 2026-09-30. Every finding carries short in-slide refs; the last
-- slide of each is a full 'Heimildir' list (DOI/PMID linked by the viewer).
-- Idempotent: upsert on slug. Edit afterwards in /admin/lectures.

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('svefn-forsenda-alls-annars', 'Svefn: forsenda alls annars', 'Hvernig svefn tengist blóðsykri, matarlyst og kviðfitu', 'slides', '[{"layout": "stat", "title": "Ein stutt nótt skiptir máli", "body": "Í hollenskri rannsókn fengu níu heilbrigðir einstaklingar aðeins fjögurra klukkustunda svefn eina nótt. Daginn eftir svaraði líkami þeirra insúlíni verr: í mælingu á insúlínnæmi þurfti um fjórðungi minni sykur til að halda blóðsykrinum stöðugum.\n\nRannsóknin var lítil og áhrifin ganga til baka þegar fólk sefur vel á ný. Hún sýnir þó hve fljótt efnaskiptin bregðast við svefni.", "stat": "≈ 25%", "refs": ["Donga o.fl., J Clin Endocrinol Metab 2010"]}, {"layout": "text", "title": "Af hverju byrjum við á svefninum?", "body": "Í heilsumatinu skoðum við svefn, næringu, hreyfingu og andlega líðan. Svefninn er oft sá hlekkur sem hinir hanga á. Eftir stutta nótt er erfiðara að velja hollan mat, orkan til að hreyfa sig er minni og þolinmæðin styttri.\n\nÍ þessari fræðslu förum við yfir hvað gerist í líkamanum á meðan við sofum, hvernig svefnleysi tengist blóðsykri, svengd og kviðfitu, og hvað þú getur gert strax í kvöld."}, {"layout": "text", "title": "Djúpsvefninn og vaxtarhormón", "body": "Nóttin skiptist í lotur af léttum svefni, djúpsvefni og draumsvefni. Djúpsvefninn er mestur fyrst á nóttunni.\n\nHjá fullorðnum kemur stærsti vaxtarhormónstoppur sólarhringsins yfirleitt skömmu eftir að við sofnum, í tengslum við fyrsta djúpsvefninn. Hjá körlum falla um 70% vaxtarhormónstoppa í svefni saman við djúpsvefn. Vaxtarhormón tekur meðal annars þátt í viðhaldi vefja og því hvernig líkaminn nýtir fitu sem orku.", "refs": ["Van Cauter og Plat, J Pediatr 1996"]}, {"layout": "bullets", "title": "Fullyrðing: „Ein slæm nótt minnkar vaxtarhormón um 70%“", "body": "Þessi tala heyrist oft, en rannsóknirnar segja aðra og áhugaverðari sögu.", "items": ["Um 70% vaxtarhormónstoppa í svefni fylgja djúpsvefni hjá körlum. Það er hlutfall, ekki mæling á tapi eftir eina nótt.", "Frá tvítugu fram á miðjan aldur minnkar djúpsvefn mikið og vaxtarhormónið dvínar samhliða því.", "Ef fólk vakir alla nóttina hverfur toppurinn sem fylgir því að sofna.", "Þegar svefn er styttur nokkrar nætur í röð bætir líkaminn að hluta upp fyrir það, meðal annars með toppi fyrr um kvöldið.", "Niðurstaða: svefn skiptir máli fyrir vaxtarhormón, en ekki hefur verið sýnt fram á 70% tap eftir eina nótt."], "refs": ["Van Cauter og Plat, J Pediatr 1996", "Van Cauter o.fl., JAMA 2000", "Spiegel o.fl., Am J Physiol 2000"]}, {"layout": "stat", "title": "Djúpsvefninn minnkar með aldrinum", "body": "Í gögnum frá 149 heilbrigðum körlum var djúpsvefn um 19% af nóttinni hjá 16–25 ára en um 3% hjá 36–50 ára. Seyting vaxtarhormóns minnkaði samhliða, og magn vaxtarhormóns tengdist djúpsvefni óháð aldri.\n\nVið getum ekki þvingað fram djúpsvefn. En við getum verndað hann: gefið okkur nægan tíma í rúminu, haldið reglu og sleppt því sem truflar hann, til dæmis áfengi.", "stat": "19% → 3%", "refs": ["Van Cauter o.fl., JAMA 2000"]}, {"layout": "text", "title": "Svefnskuld og blóðsykur", "body": "Í þekktri rannsókn fengu ungir karlar aðeins fjórar klukkustundir í rúminu sex nætur í röð. Borið saman við hvíldartímabil réðu þeir verr við sykur, kvöldgildi streituhormónsins kortisóls voru hærri og „bensíngjöf“ taugakerfisins var virkari.\n\nHöfundarnir bentu á að breytingarnar líktust því sem sést við öldrun. Þetta ástand gekk til baka þegar þátttakendur fengu að sofa út.", "refs": ["Spiegel o.fl., Lancet 1999"]}, {"layout": "stat", "title": "Svengdin eykst eftir stuttar nætur", "body": "Tvær nætur með fjögurra klukkustunda svefni breyttu svengdarboðum ungra karla. Sedduhormónið leptín lækkaði um 18%, svengdarhormónið ghrelín hækkaði um 28% og svengdin jókst um 24%.\n\nLöngunin jókst mest í orkuríkan mat með miklum kolvetnum, svo sem sætindi, snakk og brauð (33–45%). Ef þú finnur fyrir meiri löngun eftir slæma nótt er það ekki viljaleysi heldur líffræði.", "stat": "+24% svengd", "refs": ["Spiegel o.fl., Ann Intern Med 2004"]}, {"layout": "text", "title": "Svefnskortur og kviðfita", "body": "Í slembaðri rannsókn frá Mayo Clinic bjuggu tólf heilbrigðir einstaklingar á rannsóknardeild í þrjár vikur. Í tvær vikur fengu þeir annaðhvort fjögurra eða níu klukkustunda svefntækifæri og máttu borða að vild.\n\nMeð styttri svefni borðuðu þeir meira og þyngdust meira, en orkubrennslan var óbreytt. Heildarfita breyttist ekki marktækt, en fita á kviðsvæði jókst, bæði undir húð og iðrafita inni í kviðarholinu.", "refs": ["Covassin o.fl., J Am Coll Cardiol 2022"]}, {"layout": "text", "title": "Stuttur svefn og þyngd: tengsl, ekki endilega orsök", "body": "Samantekt á gögnum frá yfir 600.000 fullorðnum sýndi að þeir sem sváfu stutt voru um 55% líklegri til að vera í offitu. Hver klukkustund minni svefns tengdist aðeins hærri líkamsþyngdarstuðli.\n\nHöfundarnir benda á að erfitt sé að sanna orsakasamband út frá slíkum gögnum. Þess vegna skipta tilraunirnar á undan máli: þær sýna leiðir sem gætu skýrt tengslin.", "refs": ["Cappuccio o.fl., Sleep 2008"]}, {"layout": "stat", "title": "Góðu fréttirnar: lengri svefn getur hjálpað", "body": "Áttatíu fullorðnir í ofþyngd, sem sváfu minna en 6,5 klukkustundir, tóku þátt í slembaðri rannsókn í daglegu lífi. Helmingurinn fékk eitt ráðgjafarviðtal um svefnvenjur.\n\nSá hópur lengdi svefninn um 1,2 klukkustundir að meðaltali og borðaði um 270 kílókaloríum minna á dag en samanburðarhópurinn, án þess að vera sagt að breyta mataræðinu.", "stat": "−270 kkal/dag", "refs": ["Tasali o.fl., JAMA Intern Med 2022"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Heildarmyndin er nokkuð skýr, þótt margar rannsóknanna séu litlar:", "items": ["Fullorðnum er ráðlagt að sofa að jafnaði 7 klukkustundir eða meira á nóttu.", "Tilraunir sýna að svefnskortur dregur úr insúlínnæmi og eykur svengd, oft á fáum dögum.", "Stórar hóprannsóknir tengja stuttan svefn við ofþyngd, en sanna ekki orsök.", "Ein slembuð rannsókn í daglegu lífi bendir til að lengri svefn geti dregið úr orkuinntöku.", "Áhrifin af einni slæmri nótt ganga til baka. Það er langvarandi svefnskuld sem skiptir mestu."], "refs": ["Watson o.fl., Sleep 2015", "Spiegel o.fl., Lancet 1999", "Cappuccio o.fl., Sleep 2008", "Tasali o.fl., JAMA Intern Med 2022"]}, {"layout": "bullets", "title": "Hvað getur þú gert?", "body": "Litlar, stöðugar breytingar skila oft meiru en stór átök:", "items": ["Veldu fastan fótaferðartíma og reiknaðu háttatímann út frá honum.", "Gefðu þér svefntækifæri sem er aðeins lengra en svefninn sem þú þarft.", "Ef þú sefur of stutt: færðu háttatímann fyrr um 15–30 mínútur í einu.", "Eftir slæma nótt: skipuleggðu matinn fyrir fram, því löngunin verður meiri.", "Verndaðu fyrri hluta nætur, þegar djúpsvefninn er mestur, til dæmis með því að sleppa áfengi.", "Hrjótir þú hátt, vaknir með andköfum eða sért syfjuð/syfjaður á daginn: ræddu við lækni."]}, {"layout": "tip", "title": "Prófaðu þetta í vikunni", "body": "Bættu 30 mínútum við svefntækifærið þitt í sjö nætur. Farðu upp í rúm hálftíma fyrr en vanalega, en haltu sama fótaferðartíma.\n\nSkráðu á hverjum morgni hvernig þú svafst og hvernig matarlystin og orkan voru yfir daginn. Margir taka eftir mun á löngun í sætindi eftir aðeins nokkra daga."}, {"layout": "sources", "title": "Heimildir", "body": "Rannsóknir sem vísað er til í þessari fræðslu.", "items": ["Donga E, van Dijk M, van Dijk JG, Biermasz NR, Lammers GJ, van Kralingen KW, Corssmit EP, Romijn JA (2010). A single night of partial sleep deprivation induces insulin resistance in multiple metabolic pathways in healthy subjects. Journal of Clinical Endocrinology & Metabolism, 95(6), 2963–2968. doi:10.1210/jc.2009-2430 / PMID 20371664", "Van Cauter E, Plat L (1996). Physiology of growth hormone secretion during sleep. Journal of Pediatrics, 128(5 Pt 2), S32–S37. doi:10.1016/s0022-3476(96)70008-2 / PMID 8627466", "Van Cauter E, Leproult R, Plat L (2000). Age-related changes in slow wave sleep and REM sleep and relationship with growth hormone and cortisol levels in healthy men. JAMA, 284(7), 861–868. doi:10.1001/jama.284.7.861 / PMID 10938176", "Spiegel K, Leproult R, Colecchia EF, L''Hermite-Balériaux M, Nie Z, Copinschi G, Van Cauter E (2000). Adaptation of the 24-h growth hormone profile to a state of sleep debt. American Journal of Physiology – Regulatory, Integrative and Comparative Physiology, 279(3), R874–R883. doi:10.1152/ajpregu.2000.279.3.R874 / PMID 10956244", "Spiegel K, Leproult R, Van Cauter E (1999). Impact of sleep debt on metabolic and endocrine function. Lancet, 354(9188), 1435–1439. doi:10.1016/S0140-6736(99)01376-8 / PMID 10543671", "Spiegel K, Tasali E, Penev P, Van Cauter E (2004). Sleep curtailment in healthy young men is associated with decreased leptin levels, elevated ghrelin levels, and increased hunger and appetite. Annals of Internal Medicine, 141(11), 846–850. doi:10.7326/0003-4819-141-11-200412070-00008 / PMID 15583226", "Covassin N, Singh P, McCrady-Spitzer SK, St Louis EK, Calvin AD, Levine JA, Somers VK (2022). Effects of experimental sleep restriction on energy intake, energy expenditure, and visceral obesity. Journal of the American College of Cardiology, 79(13), 1254–1265. doi:10.1016/j.jacc.2022.01.038 / PMID 35361348", "Cappuccio FP, Taggart FM, Kandala NB, Currie A, Peile E, Stranges S, Miller MA (2008). Meta-analysis of short sleep duration and obesity in children and adults. Sleep, 31(5), 619–626. doi:10.1093/sleep/31.5.619 / PMID 18517032", "Tasali E, Wroblewski K, Kahn E, Kilkus J, Schoeller DA (2022). Effect of sleep extension on objectively assessed energy intake among adults with overweight in real-life settings: a randomized clinical trial. JAMA Internal Medicine, 182(4), 365–374. doi:10.1001/jamainternmed.2021.8098 / PMID 35129580", "Watson NF, Badr MS, Belenky G, Bliwise DL, Buxton OM, Buysse D, o.fl. (2015). Recommended amount of sleep for a healthy adult: a joint consensus statement of the American Academy of Sleep Medicine and Sleep Research Society. Sleep, 38(6), 843–844. doi:10.5665/sleep.4716 / PMID 26039963"]}]'::jsonb, 14, 'sleep', false, 11, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('svefn-likamsklukkan', 'Líkamsklukkan: reglulegur svefn og dagsbirta', 'Af hverju tímasetning svefns og birtu skiptir jafnmiklu máli og lengdin', 'slides', '[{"layout": "stat", "title": "Regla skiptir máli", "body": "Í breskri rannsókn báru um 61.000 manns hreyfimæli á úlnlið í viku og var fylgst með þeim í mörg ár á eftir.\n\nÞeir sem sváfu reglulegast, fóru að sofa og vöknuðu á svipuðum tíma dag frá degi, voru í 20–48% minni hættu á ótímabærum dauða en þeir óreglulegustu. Regla í svefni spáði betur fyrir um áhættuna en svefnlengdin. Þetta eru tengsl, ekki sönnun á orsök.", "stat": "20–48%", "refs": ["Windred o.fl., Sleep 2024"]}, {"layout": "text", "title": "Hvað er líkamsklukkan?", "body": "Djúpt í heilanum er lítill kjarni sem stýrir sólarhringstakti líkamans. Hann segir til um hvenær melatónín er losað á kvöldin, hvenær kortisól hækkar á morgnana, hvenær líkamshitinn lækkar og hvenær við erum svöng.\n\nKlukkan gengur ekki nákvæmlega á 24 klukkustundum og þarf að stilla hana daglega. Sterkasta stillimerkið er ljós sem berst í augun, sérstaklega birta að morgni og myrkur að kvöldi.", "refs": ["Brown o.fl., PLoS Biol 2022"]}, {"layout": "text", "title": "Ljósið stillir klukkuna", "body": "Bandarískir vísindamenn sendu fólk í útilegu í viku þar sem eina birtan var dagsbirta og varðeldur. Eftir vikuna hafði líkamsklukkan færst fyrr og lagað sig að sólarlagi og sólarupprás. Mest færðust þeir sem voru „kvöldtýpur“.\n\nÍ daglegu lífi fáum við of litla birtu á daginn, því við erum innandyra, og of mikla birtu á kvöldin. Það seinkar klukkunni og gerir erfiðara að vakna.", "refs": ["Wright o.fl., Curr Biol 2013"]}, {"layout": "text", "title": "Íslensk sérstaða", "body": "Á Íslandi gildir sami tími og í Greenwich, þótt landið liggi mun vestar. Í Reykjavík er sól hæst á lofti um klukkan hálftvö. Klukkan okkar er því á undan sólinni og margir vakna í raun „of snemma“ miðað við eigin líkamsklukku.\n\nOfan á þetta bætast dimmir vetrarmorgnar og bjartar sumarnætur. Hér þarf því meðvitað að sækja birtuna á morgnana og skapa myrkrið á kvöldin."}, {"layout": "text", "title": "Félagsleg flugþreyta", "body": "Margir vakna við vekjaraklukku á virkum dögum en sofa lengur um helgar. Munurinn á miðju svefntímabilinu á vinnudögum og frídögum kallast félagsleg flugþreyta, eins og að fljúga yfir tímabelti á hverjum föstudegi og aftur heim á mánudegi.\n\nÍ stórri evrópskri rannsókn tengdist meiri félagsleg flugþreyta hærri líkamsþyngdarstuðli, óháð því hve lengi fólk svaf.", "refs": ["Wittmann o.fl., Chronobiol Int 2006", "Roenneberg o.fl., Curr Biol 2012"]}, {"layout": "stat", "title": "Óreglulegur svefn og efnaskipti", "body": "Í bandarískri rannsókn báru rúmlega 2.000 fullorðnir hreyfimæli í viku. Fyrir hverja klukkustund sem tíminn þegar fólk sofnaði flakkaði til milli daga voru líkurnar á efnaskiptavillu 23% meiri. Efnaskiptavilla er samspil hás blóðþrýstings, blóðsykurs, blóðfitu og kviðfitu.\n\nTengslin héldust þótt tekið væri tillit til svefnlengdar og sáust líka þegar fólki var fylgt eftir í nokkur ár.", "stat": "+23%", "refs": ["Huang og Redline, Diabetes Care 2019"]}, {"layout": "quote", "title": "Niðurstaða sérfræðinga", "body": "„Regla á því hvenær við sofnum og vöknum skiptir máli fyrir heilsu, öryggi og afköst.“\n\nSami hópur bendir á að ef svefninn er of stuttur í vinnuvikunni getur verið gagnlegt að bæta hann upp um helgar. Markmiðið er því ekki að banna lengri svefn, heldur að þurfa minna á honum að halda.", "caption": "Samantekt sérfræðingahóps National Sleep Foundation, 2023 (þýtt)", "refs": ["Sletten o.fl., Sleep Health 2023"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Rannsóknir á reglu og birtu eru flestar hóprannsóknir. Þær sýna tengsl, en niðurstöðurnar eru samhljóða:", "items": ["Reglulegri svefn tengist minni dánartíðni og minni hættu á efnaskiptavillu.", "Í yfir 88.000 manna rannsókn tengdust bjartari dagar minni áhættu og bjartari nætur meiri áhættu.", "Tilraunir sýna að dagsbirta færir líkamsklukkuna fyrr og kvöldljós seinkar henni.", "Sérfræðingahópar mæla með reglu á svefntíma og markvissri birtu að degi."], "refs": ["Windred o.fl., Sleep 2024", "Windred o.fl., PNAS 2024", "Huang og Redline, Diabetes Care 2019", "Sletten o.fl., Sleep Health 2023"]}, {"layout": "bullets", "title": "Birta á daginn, myrkur á kvöldin", "body": "Alþjóðlegur hópur sérfræðinga setti fram viðmið um birtu, mælda við augað:", "items": ["Á daginn: mikil birta, helst dagsbirta. Jafnvel skýjaður dagur úti er mun bjartari en venjuleg skrifstofa.", "Síðustu þrjár klukkustundir fyrir svefn: dauf og hlý ljós.", "Í svefnherberginu: sem næst algjört myrkur.", "Farðu út sem fyrst eftir að þú vaknar, til dæmis í göngutúr eða með kaffibollann á svölunum.", "Á sumrin: myrkvunartjöld eða svefngríma hjálpa gegn björtum nóttum."], "refs": ["Brown o.fl., PLoS Biol 2022"]}, {"layout": "bullets", "title": "Regla í framkvæmd", "body": "Fótaferðartíminn er akkerið. Háttatíminn fylgir á eftir:", "items": ["Vaknaðu á svipuðum tíma alla daga, líka um helgar.", "Reyndu að láta muninn á virkum dögum og frídögum ekki fara yfir klukkustund.", "Farðu í rúmið þegar þú ert syfjuð eða syfjaður, en ekki fyrr en á þínum venjulega tíma.", "Borðaðu á svipuðum tímum dag frá degi. Máltíðir eru líka stillimerki fyrir líkamann.", "Eftir stutta nótt: frekar stuttur blundur snemma dags en að sofa langt fram eftir."]}, {"layout": "text", "title": "Vaktavinna og dimmir vetrarmorgnar", "body": "Vaktavinna gerir reglu erfiða og þá skiptir enn meira máli að hafa myrkur þegar sofið er og birtu þegar vakað er. Ræddu við lækni eða starfsheilsuþjónustu ef vaktirnar fara illa í þig.\n\nSumir nota dagsbirtulampa á dimmum vetrarmorgnum. Ef þú íhugar það skaltu ræða við lækni fyrst, sérstaklega ef þú ert með augnsjúkdóm, tekur lyf sem auka ljósnæmi eða hefur sögu um geðhvörf."}, {"layout": "tip", "title": "Prófaðu þetta í vikunni", "body": "Veldu einn fótaferðartíma og haltu honum í sjö daga, líka um helgina. Farðu út í að minnsta kosti tíu mínútur fyrir hádegi, helst sem fyrst eftir að þú vaknar.\n\nDeyfðu ljósin heima tveimur til þremur tímum fyrir svefn. Skráðu hvenær þú verður syfjuð eða syfjaður á kvöldin. Hjá mörgum færist syfjan fyrr þegar líður á vikuna."}, {"layout": "sources", "title": "Heimildir", "body": "Rannsóknir sem vísað er til í þessari fræðslu.", "items": ["Windred DP, Burns AC, Lane JM, Saxena R, Rutter MK, Cain SW, Phillips AJK (2024). Sleep regularity is a stronger predictor of mortality risk than sleep duration: a prospective cohort study. Sleep, 47(1), zsad253. doi:10.1093/sleep/zsad253 / PMID 37738616", "Brown TM, Brainard GC, Cajochen C, Czeisler CA, Hanifin JP, Lockley SW, o.fl. (2022). Recommendations for daytime, evening, and nighttime indoor light exposure to best support physiology, sleep, and wakefulness in healthy adults. PLoS Biology, 20(3), e3001571. doi:10.1371/journal.pbio.3001571 / PMID 35298459", "Wright KP Jr, McHill AW, Birks BR, Griffin BR, Rusterholz T, Chinoy ED (2013). Entrainment of the human circadian clock to the natural light-dark cycle. Current Biology, 23(16), 1554–1558. doi:10.1016/j.cub.2013.06.039 / PMID 23910656", "Wittmann M, Dinich J, Merrow M, Roenneberg T (2006). Social jetlag: misalignment of biological and social time. Chronobiology International, 23(1–2), 497–509. doi:10.1080/07420520500545979 / PMID 16687322", "Roenneberg T, Allebrandt KV, Merrow M, Vetter C (2012). Social jetlag and obesity. Current Biology, 22(10), 939–943. doi:10.1016/j.cub.2012.03.038 / PMID 22578422", "Huang T, Redline S (2019). Cross-sectional and prospective associations of actigraphy-assessed sleep regularity with metabolic abnormalities: the Multi-Ethnic Study of Atherosclerosis. Diabetes Care, 42(8), 1422–1429. doi:10.2337/dc19-0596 / PMID 31167888", "Sletten TL, Weaver MD, Foster RG, Gozal D, Klerman EB, Rajaratnam SMW, o.fl. (2023). The importance of sleep regularity: a consensus statement of the National Sleep Foundation sleep timing and variability panel. Sleep Health, 9(6), 801–820. doi:10.1016/j.sleh.2023.07.016 / PMID 37684151", "Windred DP, Burns AC, Lane JM, Olivier P, Rutter MK, Saxena R, Phillips AJK, Cain SW (2024). Brighter nights and darker days predict higher mortality risk: a prospective analysis of personal light exposure in >88,000 individuals. Proceedings of the National Academy of Sciences USA, 121(43), e2405924121. doi:10.1073/pnas.2405924121 / PMID 39405349"]}]'::jsonb, 13, 'sleep', false, 12, true)
