  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('svefn-umhverfi-og-kvoldvenjur', 'Svefnumhverfi og kvöldvenjur', 'Koffín, áfengi, skjáir, hitastig og kvöldmatur: hvað skiptir máli?', 'slides', '[{"layout": "stat", "title": "Kaffið klukkan fimm", "body": "Í bandarískri rannsókn tóku heilbrigðir einstaklingar 400 mg af koffíni, sem samsvarar nokkrum kaffibollum, sex klukkustundum fyrir svefn. Svefninn, mældur með tæki, styttist um meira en klukkustund.\n\nÞað merkilega: fólkið tók sjálft lítið eftir þessu. Svefnmælingin sagði aðra sögu en tilfinningin.", "stat": "> 1 klst.", "refs": ["Drake o.fl., J Clin Sleep Med 2013"]}, {"layout": "text", "title": "Hvernig virkar koffín?", "body": "Á meðan við vökum safnast upp efnið adenósín í heilanum og byggir upp svefnþrýsting. Koffín hindrar að adenósín nái til viðtaka sinna og því finnum við minna fyrir þreytunni. Hún hverfur þó ekki.\n\nKoffín er klukkustundum saman að brotna niður og hraðinn er mjög einstaklingsbundinn. Erfðir, reykingar, getnaðarvarnarpillan, meðganga og ýmis lyf hafa áhrif. Sumir sofa vel eftir kvöldkaffi, aðrir ekki.", "refs": ["Nehlig, Pharmacol Rev 2018"]}, {"layout": "stat", "title": "Hversu snemma er síðasti bollinn?", "body": "Samantekt 24 rannsókna sýndi að koffín stytti svefninn um 45 mínútur að meðaltali, lengdi tímann sem tók að sofna og minnkaði djúpsvefn.\n\nHöfundarnir mátu að síðasti venjulegi kaffibollinn ætti að vera að minnsta kosti 8,8 klukkustundum fyrir svefn. Ef þú ferð að sofa klukkan 23 er það um klukkan 14. Stærri skammtar, eins og orkudrykkir og æfingaduft, þurfa enn lengri tíma.", "stat": "8,8 klst.", "refs": ["Gardiner o.fl., Sleep Med Rev 2023", "EFSA 2015"]}, {"layout": "text", "title": "Áfengi: blekkjandi svefnlyf", "body": "Áfengi hjálpar mörgum að sofna hraðar og fyrri hluti nætur getur orðið dýpri. En í seinni hluta nætur, þegar líkaminn hefur brotið áfengið niður, verður svefninn órólegri og slitróttari.\n\nDraumsvefninn seinkar og minnkar, sérstaklega við meðalstóra og stóra skammta. Draumsvefn tengist meðal annars úrvinnslu tilfinninga og minni. Fólk vaknar því oft þreytt, þótt það hafi „rotast“ strax.", "refs": ["Ebrahim o.fl., Alcohol Clin Exp Res 2013"]}, {"layout": "stat", "title": "Jafnvel lítið magn sést í hjartslættinum", "body": "Finnsk rannsókn fylgdi rúmlega 4.000 starfsmönnum með hjartsláttarmælingum í daglegu lífi. Fyrstu þrjár klukkustundir svefnsins var endurheimt, metin út frá breytileika hjartsláttar, minni eftir áfengi.\n\nHún minnkaði um 9 prósentustig eftir lítið magn, 24 eftir miðlungsmagn og 39 eftir mikið magn. Hvorki regluleg hreyfing né ungur aldur vernduðu gegn áhrifunum.", "stat": "−39", "refs": ["Pietilä o.fl., JMIR Ment Health 2018"]}, {"layout": "text", "title": "Skjáir og kvöldljós", "body": "Í tilraun lásu þátttakendur annaðhvort af upplýstri lesbretti eða úr prentaðri bók á kvöldin í nokkra daga. Eftir lesbrettið voru þeir lengur að sofna, melatónín var minna, líkamsklukkan hafði seinkað og þeir voru síður vakandi morguninn eftir.\n\nÍ daglegu lífi skiptir líka máli hvað við gerum í símanum. Spennandi efni og endalaust skrun halda heilanum vakandi og ýta háttatímanum aftar.", "refs": ["Chang o.fl., PNAS 2015"]}, {"layout": "text", "title": "Svalt svefnherbergi", "body": "Til að sofna þarf kjarnhiti líkamans að lækka. Rannsóknir sýna að hiti í svefnherberginu eykur vöku og dregur úr djúpsvefni og draumsvefni, sérstaklega í röku lofti.\n\nKuldi truflar síður svefnstigin ef sængin er nógu hlý, en getur haft áhrif á hjarta og æðakerfi. Markmiðið er því svalt og vel loftað herbergi, með sæng og náttfötum sem halda hæfilegum hita.", "refs": ["Okamoto-Mizuno og Mizuno, J Physiol Anthropol 2012"]}, {"layout": "stat", "title": "Heit sturta fyrir svefninn", "body": "Það hljómar öfugsnúið, en heit sturta eða bað getur hjálpað. Samantekt rannsókna sýndi að 40–42,5 °C heitt vatn einni til tveimur klukkustundum fyrir svefn tengdist betri svefngæðum. Jafnvel tíu mínútur styttu tímann sem tók að sofna.\n\nSkýringin: blóðflæði út í hendur og fætur eykst, líkaminn losar hita og kjarnhitinn fellur hraðar þegar þú leggst út af.", "stat": "1–2 klst.", "refs": ["Haghayegh o.fl., Sleep Med Rev 2019"]}, {"layout": "text", "title": "Seinn kvöldmatur", "body": "Í tilraun borðuðu 20 heilbrigðir ungir einstaklingar sömu máltíð annaðhvort klukkan 18 eða 22 og fóru að sofa klukkan 23. Eftir seinni máltíðina var blóðsykur hærri um nóttina, líkaminn brenndi minni fitu og kortisól hækkaði. Svefnstigin sjálf breyttust ekki.\n\nÁhrifin voru mest hjá þeim sem voru vanir að fara snemma að sofa. Rannsóknin var stutt og lítil, en bendir til að tímasetning máltíða skipti máli.", "refs": ["Gu o.fl., J Clin Endocrinol Metab 2020"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Styrkur rannsóknanna er misjafn, en skilaboðin eru samhljóða:", "items": ["Koffín: sterkust gögn. Samantekt 24 rannsókna sýnir skýr áhrif á svefnlengd og djúpsvefn.", "Áfengi: vel skjalfest að það raskar seinni hluta nætur og draumsvefni.", "Hitastig og heit sturta: samhljóða niðurstöður, en rannsóknirnar eru fáar og litlar.", "Skjáir og seinar máltíðir: litlar tilraunir sem benda í sömu átt."], "refs": ["Gardiner o.fl., Sleep Med Rev 2023", "Ebrahim o.fl., Alcohol Clin Exp Res 2013", "Haghayegh o.fl., Sleep Med Rev 2019", "Chang o.fl., PNAS 2015", "Gu o.fl., J Clin Endocrinol Metab 2020"]}, {"layout": "bullets", "title": "Svefnherbergið", "body": "Gerðu herbergið að stað sem líkaminn tengir við svefn:", "items": ["Myrkur: myrkvunartjöld eða svefngríma, sérstaklega á björtum sumarnóttum.", "Svalt: loftaðu út fyrir svefninn og hafðu ofninn lágt stilltan.", "Kyrrð: eyrnatappar eða jafn bakgrunnshljóður ef umhverfið er hávært.", "Síminn fyrir utan herbergið og venjuleg vekjaraklukka í staðinn.", "Rúmið fyrir svefn og nánd, ekki fyrir vinnu eða sjónvarpsáhorf."]}, {"layout": "bullets", "title": "Kvöldrútína síðustu klukkustundina", "body": "Sama röð á hverju kvöldi hjálpar líkamanum að stilla sig inn á svefn:", "items": ["Deyfðu ljósin og slökktu á skjáum sem þú þarft ekki að nota.", "Skrifaðu niður það sem þú ætlar að gera á morgun, svo hugurinn þurfi ekki að muna það.", "Farðu í heita sturtu eða bað einni til tveimur klukkustundum fyrir svefn.", "Lestu úr bók, hlustaðu á rólega tónlist eða gerðu léttar teygjur.", "Ef þú ert svöng eða svangur: léttur biti frekar en stór máltíð."], "refs": ["Haghayegh o.fl., Sleep Med Rev 2019"]}, {"layout": "tip", "title": "Prófaðu þetta í vikunni", "body": "Settu koffínstopp klukkan 14 í sjö daga. Það á við um kaffi, svart og grænt te, kóladrykki, orkudrykki og æfingaduft.\n\nBerðu saman hvernig þú sefur og hvernig þér líður á morgnana, miðað við vikuna á undan. Ef þér finnst erfitt að sleppa síðdegisbollanum geturðu prófað koffínlaust kaffi."}, {"layout": "sources", "title": "Heimildir", "body": "Rannsóknir sem vísað er til í þessari fræðslu.", "items": ["Drake C, Roehrs T, Shambroom J, Roth T (2013). Caffeine effects on sleep taken 0, 3, or 6 hours before going to bed. Journal of Clinical Sleep Medicine, 9(11), 1195–1200. doi:10.5664/jcsm.3170 / PMID 24235903", "Nehlig A (2018). Interindividual differences in caffeine metabolism and factors driving caffeine consumption. Pharmacological Reviews, 70(2), 384–411. doi:10.1124/pr.117.014407 / PMID 29514871", "Gardiner C, Weakley J, Burke LM, Roach GD, Sargent C, Maniar N, Townshend A, Halson SL (2023). The effect of caffeine on subsequent sleep: a systematic review and meta-analysis. Sleep Medicine Reviews, 69, 101764. doi:10.1016/j.smrv.2023.101764 / PMID 36870101", "EFSA Panel on Dietetic Products, Nutrition and Allergies (NDA) (2015). Scientific opinion on the safety of caffeine. EFSA Journal, 13(5), 4102. doi:10.2903/j.efsa.2015.4102", "Ebrahim IO, Shapiro CM, Williams AJ, Fenwick PB (2013). Alcohol and sleep I: effects on normal sleep. Alcoholism: Clinical and Experimental Research, 37(4), 539–549. doi:10.1111/acer.12006 / PMID 23347102", "Pietilä J, Helander E, Korhonen I, Myllymäki T, Kujala UM, Lindholm H (2018). Acute effect of alcohol intake on cardiovascular autonomic regulation during the first hours of sleep in a large real-world sample of Finnish employees: observational study. JMIR Mental Health, 5(1), e23. doi:10.2196/mental.9519 / PMID 29549064", "Chang AM, Aeschbach D, Duffy JF, Czeisler CA (2015). Evening use of light-emitting eReaders negatively affects sleep, circadian timing, and next-morning alertness. Proceedings of the National Academy of Sciences USA, 112(4), 1232–1237. doi:10.1073/pnas.1418490112 / PMID 25535358", "Okamoto-Mizuno K, Mizuno K (2012). Effects of thermal environment on sleep and circadian rhythm. Journal of Physiological Anthropology, 31(1), 14. doi:10.1186/1880-6805-31-14 / PMID 22738673", "Haghayegh S, Khoshnevis S, Smolensky MH, Diller KR, Castriotta RJ (2019). Before-bedtime passive body heating by warm shower or bath to improve sleep: a systematic review and meta-analysis. Sleep Medicine Reviews, 46, 124–135. doi:10.1016/j.smrv.2019.04.008 / PMID 31102877", "Gu C, Brereton N, Schweitzer A, Cotter M, Duan D, Børsheim E, o.fl. (2020). Metabolic effects of late dinner in healthy volunteers – a randomized crossover clinical trial. Journal of Clinical Endocrinology & Metabolism, 105(8), 2789–2802. doi:10.1210/clinem/dgaa354 / PMID 32525525"]}]'::jsonb, 14, 'sleep', false, 13, true)
