insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('svefn-baetiefni-og-medferd', 'Bætiefni, svefnlyf og hvað virkar', 'Magnesíum, melatónín, svefnlyf og hugræn atferlismeðferð við svefnleysi', 'slides', '[{"layout": "quote", "title": "Fyrsta meðferð er ekki pilla", "body": "„Mælt er með því að allir fullorðnir sjúklingar fái hugræna atferlismeðferð við svefnleysi sem fyrstu meðferð við langvinnu svefnleysi.“\n\nÞetta er sterk ráðlegging, byggð á miðlungsgóðum gögnum. Evrópskar leiðbeiningar frá 2023 segja það sama, óháð aldri og líka þegar fólk er með aðra sjúkdóma.", "caption": "Bandaríska lyflæknafélagið (ACP), klínískar leiðbeiningar 2016 (þýtt)", "refs": ["Qaseem o.fl., Ann Intern Med 2016", "Riemann o.fl., J Sleep Res 2023"]}, {"layout": "text", "title": "Slæmar nætur eða svefnleysi?", "body": "Flestir eiga stundum erfiðar nætur, til dæmis vegna álags, veikinda eða ferðalaga. Það er eðlilegt og gengur oftast yfir.\n\nLangvinnt svefnleysi er annað: erfiðleikar við að sofna eða halda svefni flestar nætur í margar vikur eða mánuði, sem hafa áhrif á líðan og getu yfir daginn. Þá er full ástæða til að ræða við lækni, því til eru meðferðir sem rannsóknir styðja vel."}, {"layout": "text", "title": "Hvað er HAM-S?", "body": "Hugræn atferlismeðferð við svefnleysi (HAM-S) er skipulögð meðferð, oftast í fjórum til átta skiptum, hjá fagaðila eða í stafrænu formi. Hún vinnur á því sem viðheldur svefnleysinu, ekki bara einkennunum.\n\nHelstu þættir eru áreitisstjórnun, svefnþjöppun, vinna með hugsanir um svefn, slökun og fræðsla. Bandarísku svefnlæknasamtökin mæla eindregið með fjölþátta HAM-S.", "refs": ["Edinger o.fl., J Clin Sleep Med 2021", "Riemann o.fl., J Sleep Res 2023"]}, {"layout": "stat", "title": "Hvað skilar HAM-S?", "body": "Samantekt 20 slembaðra rannsókna með rúmlega 1.100 þátttakendum sýndi að eftir HAM-S sofnaði fólk um 19 mínútum fyrr. Það var líka 26 mínútum skemur vakandi um nóttina og svefnnýting batnaði um tæp 10 prósentustig.\n\nÁrangurinn virtist haldast eftir að meðferð lauk og engar aukaverkanir voru skráðar.", "stat": "−19 mín.", "refs": ["Trauer o.fl., Ann Intern Med 2015"]}, {"layout": "bullets", "title": "Tvö lykilverkfæri úr HAM-S", "body": "Þetta eru kjarnaatriði meðferðarinnar. Svefnþjöppun er best að gera með leiðsögn fagaðila:", "items": ["Áreitisstjórnun: rúmið er fyrir svefn. Ef þú liggur lengi andvaka skaltu fara fram og koma aftur þegar syfjan kemur.", "Sami fótaferðartími alla daga, óháð því hvernig nóttin var.", "Svefnþjöppun: tími í rúminu er styttur tímabundið svo svefninn þéttist og lengdur svo smám saman.", "Svefnþjöppun hentar ekki öllum, til dæmis ekki fólki með flogaveiki eða geðhvörf eða sem ekur vinnutæki. Ræddu við lækni."], "refs": ["Edinger o.fl., J Clin Sleep Med 2021"]}, {"layout": "text", "title": "Magnesíum: hvað segja rannsóknirnar?", "body": "Samantekt fann aðeins þrjár litlar rannsóknir, með samtals 151 eldri einstaklingi. Þátttakendur sem fengu magnesíum sofnuðu um 17 mínútum fyrr, en heildarsvefn jókst ekki marktækt. Gæði gagnanna voru lítil eða mjög lítil.\n\nÍ nýlegri rannsókn á 155 fullorðnum með lélegan svefn bætti magnesíumbisglýsínat svefnleysiseinkenni lítillega eftir fjórar vikur. Áhrifin voru lítil og sumir höfundanna hafa tengsl við bætiefnaframleiðendur.", "refs": ["Mah og Pitre, BMC Complement Med Ther 2021", "Schuster o.fl., Nat Sci Sleep 2025"]}, {"layout": "text", "title": "Magnesíumglýsínat: heiðarlegt mat", "body": "Magnesíumglýsínat er oft ráðlagt fyrir svefninn. Gögnin benda til að áhrifin séu í besta falli lítil og óvíst hverjir njóta þeirra. Mögulega þeir sem fá lítið magnesíum úr fæðunni, en það þarf að rannsaka betur.\n\nMagnesíum fæst úr hnetum, fræjum, baunum, heilkorni og grænu grænmeti. Ef þú íhugar bætiefni skaltu ræða við lækni eða lyfjafræðing, sérstaklega ef þú ert með nýrnasjúkdóm eða tekur önnur lyf.", "refs": ["Mah og Pitre, BMC Complement Med Ther 2021", "Schuster o.fl., Nat Sci Sleep 2025"]}, {"layout": "text", "title": "Melatónín: klukkuboð, ekki svefnpilla", "body": "Melatónín er hormón sem heilinn losar þegar dimmir og segir líkamanum að nótt sé komin. Í samantekt 19 rannsókna styttist tíminn sem tók að sofna um 7 mínútur og svefninn lengdist um 8 mínútur. Áhrifin eru raunveruleg en hófleg.\n\nBandarísku svefnlæknasamtökin mæla ekki með melatóníni við langvinnu svefnleysi. Evrópskar leiðbeiningar telja að forðamelatónín geti komið til greina í allt að þrjá mánuði hjá 55 ára og eldri.", "refs": ["Ferracioli-Oda o.fl., PLoS One 2013", "Sateia o.fl., J Clin Sleep Med 2017", "Riemann o.fl., J Sleep Res 2023"]}, {"layout": "stat", "title": "Ekki alltaf það sem stendur á miðanum", "body": "Kanadísk rannsókn mældi melatónín í 31 bætiefni. Magnið var frá 83% minna upp í 478% meira en stóð á umbúðunum, og munur milli framleiðslulota sömu vöru var mikill. Í átta vörum fannst líka serótónín.\n\nÞetta á við um bætiefni almennt: þau fara ekki í gegnum sama gæðaeftirlit og lyf.", "stat": "−83% til +478%", "refs": ["Erland og Saxena, J Clin Sleep Med 2017"]}, {"layout": "text", "title": "Hvar melatónín getur átt við", "body": "Melatónín virkar best sem tímamerki. Samantekt Cochrane á flugþreytu eftir flug yfir fimm eða fleiri tímabelti fann að melatónín tekið á réttum tíma dró úr einkennum í níu af tíu rannsóknum.\n\nTímasetningin skiptir öllu. Rangt tekið getur það valdið syfju á röngum tíma og seinkað aðlögun. Ræddu við lækni um hvort og hvernig það hentar þér, því melatónín getur haft milliverkanir við lyf, til dæmis blóðþynningarlyf.", "refs": ["Herxheimer og Petrie, Cochrane 2002"]}, {"layout": "text", "title": "Svefnlyf: hjálp til skamms tíma", "body": "Svefnlyf geta átt rétt á sér í stuttan tíma og þá í samráði við lækni. Leiðbeiningar mæla með að ákvörðunin sé tekin saman og að kostir, áhættur og kostnaður séu ræddir.\n\nHjá 60 ára og eldri lengdu svefnlyf svefninn um 25 mínútur að meðaltali. Aukaverkanir á hugsun og minni voru hins vegar nærri fimmfalt algengari. Þrettán þurftu meðferð til að einn svæfi betur, en fyrir hverja sex varð einn fyrir aukaverkun. Hættu aldrei skyndilega á lyfjum án samráðs við lækni.", "refs": ["Qaseem o.fl., Ann Intern Med 2016", "Glass o.fl., BMJ 2005"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Svona raða leiðbeiningar og samantektir úrræðunum:", "items": ["HAM-S: fyrsta meðferð við langvinnu svefnleysi, sterkustu gögnin og áhrif sem haldast.", "Svefnlyf: hófleg áhrif, raunverulegar áhættur. Til skamms tíma, í samráði við lækni.", "Melatónín: hófleg áhrif á svefnleysi, gagnlegra sem tímamerki, til dæmis við flugþreytu.", "Magnesíum: veik gögn og lítil áhrif.", "Ekki mælt með: ofnæmislyfjum sem svefnlyfi, garðabrúðu eða tryptófani.", "Góðar svefnvenjur einar og sér duga yfirleitt ekki sem meðferð við langvinnu svefnleysi."], "refs": ["Qaseem o.fl., Ann Intern Med 2016", "Sateia o.fl., J Clin Sleep Med 2017", "Edinger o.fl., J Clin Sleep Med 2021", "Riemann o.fl., J Sleep Res 2023"]}, {"layout": "bullets", "title": "Hvenær er rétt að leita til læknis?", "body": "Ræddu við lækni ef eitthvað af þessu á við um þig:", "items": ["Svefninn hefur verið slæmur flestar nætur í meira en nokkrar vikur.", "Þú hrýtur hátt, einhver hefur tekið eftir öndunarhléum eða þú vaknar með andköfum.", "Þú ert mjög syfjuð eða syfjaður á daginn, til dæmis undir stýri.", "Þú finnur fyrir óþægindum eða fiðringi í fótum á kvöldin.", "Depurð, kvíði eða áhyggjur halda fyrir þér vöku.", "Þú hefur notað svefnlyf eða bætiefni lengi og vilt endurskoða það."]}, {"layout": "tip", "title": "Prófaðu þetta í vikunni", "body": "Byrjaðu á svefndagbók í tvær vikur. Skráðu á hverjum morgni hvenær þú fórst upp í rúm, hvenær þú sofnaðir, hve lengi þú varst vakandi um nóttina og hvenær þú fórst á fætur. Skráðu líka koffín, áfengi og hreyfingu.\n\nDagbókin er grunnurinn í HAM-S og kemur að góðum notum ef þú ræðir svefninn við lækni eða heilsuþjálfara."}, {"layout": "sources", "title": "Heimildir", "body": "Rannsóknir og leiðbeiningar sem vísað er til í þessari fræðslu.", "items": ["Qaseem A, Kansagara D, Forciea MA, Cooke M, Denberg TD; Clinical Guidelines Committee of the American College of Physicians (2016). Management of chronic insomnia disorder in adults: a clinical practice guideline from the American College of Physicians. Annals of Internal Medicine, 165(2), 125–133. doi:10.7326/M15-2175 / PMID 27136449", "Riemann D, Espie CA, Altena E, Arnardottir ES, Baglioni C, Bassetti CLA, o.fl. (2023). The European Insomnia Guideline: an update on the diagnosis and treatment of insomnia 2023. Journal of Sleep Research, 32(6), e14035. doi:10.1111/jsr.14035 / PMID 38016484", "Edinger JD, Arnedt JT, Bertisch SM, Carney CE, Harrington JJ, Lichstein KL, o.fl. (2021). Behavioral and psychological treatments for chronic insomnia disorder in adults: an American Academy of Sleep Medicine clinical practice guideline. Journal of Clinical Sleep Medicine, 17(2), 255–262. doi:10.5664/jcsm.8986 / PMID 33164742", "Trauer JM, Qian MY, Doyle JS, Rajaratnam SM, Cunnington D (2015). Cognitive behavioral therapy for chronic insomnia: a systematic review and meta-analysis. Annals of Internal Medicine, 163(3), 191–204. doi:10.7326/M14-2841 / PMID 26054060", "Mah J, Pitre T (2021). Oral magnesium supplementation for insomnia in older adults: a systematic review & meta-analysis. BMC Complementary Medicine and Therapies, 21(1), 125. doi:10.1186/s12906-021-03297-z / PMID 33865376 (leiðrétting 2024: doi:10.1186/s12906-024-04721-w)", "Schuster J, Cycelskij I, Lopresti A, Hahn A (2025). Magnesium bisglycinate supplementation in healthy adults reporting poor sleep: a randomized, placebo-controlled trial. Nature and Science of Sleep, 17, 2027–2040. doi:10.2147/NSS.S524348 / PMID 40918053", "Ferracioli-Oda E, Qawasmi A, Bloch MH (2013). Meta-analysis: melatonin for the treatment of primary sleep disorders. PLoS One, 8(5), e63773. doi:10.1371/journal.pone.0063773 / PMID 23691095", "Sateia MJ, Buysse DJ, Krystal AD, Neubauer DN, Heald JL (2017). Clinical practice guideline for the pharmacologic treatment of chronic insomnia in adults: an American Academy of Sleep Medicine clinical practice guideline. Journal of Clinical Sleep Medicine, 13(2), 307–349. doi:10.5664/jcsm.6470 / PMID 27998379", "Erland LA, Saxena PK (2017). Melatonin natural health products and supplements: presence of serotonin and significant variability of melatonin content. Journal of Clinical Sleep Medicine, 13(2), 275–281. doi:10.5664/jcsm.6462 / PMID 27855744", "Herxheimer A, Petrie KJ (2002). Melatonin for the prevention and treatment of jet lag. Cochrane Database of Systematic Reviews, (2), CD001520. doi:10.1002/14651858.CD001520 / PMID 12076414", "Glass J, Lanctôt KL, Herrmann N, Sproule BA, Busto UE (2005). Sedative hypnotics in older people with insomnia: meta-analysis of risks and benefits. BMJ, 331(7526), 1169. doi:10.1136/bmj.38623.768588.47 / PMID 16284208"]}]'::jsonb, 15, 'sleep', false, 14, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('hreyfing-styrktarthjalfun-verdmaetasti-vefurinn', 'Styrktarþjálfun: verðmætasti vefurinn', 'Af hverju vöðvarnir skipta máli fyrir blóðsykur, efnaskipti og heilsu – og hvernig þú byggir þá upp á öruggan hátt', 'slides', '[{"layout": "stat", "title": "Vöðvarnir eru stærsti sykurnotandinn", "stat": "~80%", "caption": "af þeim sykri sem insúlín beinir úr blóðinu fer inn í beinagrindarvöðva (mælt í tilraunaaðstæðum)", "body": "Flestir hugsa um vöðva sem eitthvað til að lyfta hlutum. En vöðvarnir eru líka stærsta „geymsla“ líkamans fyrir blóðsykur. Þegar þú borðar og insúlín hækkar tekur vöðvavefurinn við stærstum hluta sykursins. Þess vegna tengist magn og ástand vöðvanna því hvernig líkaminn ræður við blóðsykur.", "refs": ["DeFronzo & Tripathy, Diabetes Care 2009"]}, {"layout": "text", "title": "Vöðvinn er efnaskiptalíffæri", "body": "Í vöðvafrumum eru flutningsprótein, GLUT4, sem hleypa sykri inn í frumuna. Insúlín kallar þau upp á yfirborðið – en það gerir vöðvasamdráttur líka, jafnvel án insúlíns. Sykurinn er geymdur sem glýkógen og notaður sem orka.\n\nMeiri vöðvamassi þýðir meira geymslurými. Í stórri bandarískri rannsókn (13.644 manns) tengdist hver 10% aukning í hlutfallslegum vöðvamassa um 11% minna insúlínviðnámi. Þetta er þversniðsrannsókn og sýnir tengsl, ekki orsök.", "refs": ["DeFronzo & Tripathy, Diabetes Care 2009", "Srikanthan & Karlamangla, JCEM 2011"]}, {"layout": "bullets", "title": "Hvað er insúlínviðnám?", "body": "Insúlínviðnám þýðir að frumurnar svara insúlíni verr en áður. Brisið þarf þá að framleiða meira insúlín til að halda blóðsykrinum í skefjum.", "items": ["Vöðvarnir taka verr við sykri og hann staldrar lengur við í blóðinu", "Brisið bætir það upp með meira insúlíni – oft árum saman áður en blóðsykur hækkar", "Insúlínviðnám í vöðvum er talið lykilþáttur í þróun sykursýki af tegund 2", "Kyrrseta, mikil innyflafita, svefnleysi og erfðir tengjast insúlínviðnámi", "Hreyfing er ein best rannsakaða leiðin til að bæta insúlínnæmi"], "refs": ["DeFronzo & Tripathy, Diabetes Care 2009"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Styrktarþjálfun hefur verið rannsökuð bæði í stórum hóprannsóknum og slembiröðuðum rannsóknum.", "items": ["Samantekt 16 hóprannsókna: styrktaræfingar tengdust 10–17% minni áhættu á ótímabærum dauða, hjartasjúkdómum, krabbameini og sykursýki", "Mestur ávinningur sást við um 30–60 mínútur á viku", "Hjá fólki með sykursýki 2 lækkaði skipulögð styrktarþjálfun langtímablóðsykur (HbA1c) að meðaltali um 0,57 prósentustig", "Í 54 rannsóknum lækkaði styrktarþjálfun fituhlutfall að meðaltali um 1,5 prósentustig"], "refs": ["Momma o.fl., Br J Sports Med 2022", "Umpierre o.fl., JAMA 2011", "Wewege o.fl., Sports Med 2022"]}, {"layout": "text", "title": "Styrkur og innyflafita – heiðarleg mynd", "body": "Innyflafita, fitan inni í kviðarholinu, tengist sterkt insúlínviðnámi. Nýleg safngreining sýndi að styrktarþjálfun minnkaði innyflafitu í meðallagi miklum mæli miðað við engar æfingar.\n\nEldri safngreining fann hins vegar skýrari áhrif af þolþjálfun en styrktarþjálfun á innyflafitu. Niðurstaðan: styrkur einn og sér gerir gagn, en samsetning styrks og þols – eins og í þessu kerfi – er líklegust til að skila mestu.", "refs": ["Wewege o.fl., Sports Med 2022", "Ismail o.fl., Obes Rev 2012"]}, {"layout": "text", "title": "Brennir viðgerðin á vöðvunum fitu?", "body": "Að hluta, en minna en oft er haldið fram. Eftir erfiða styrktaræfingu er nýmyndun vöðvapróteina aukin í allt að 48 klukkustundir. Það kostar orku.\n\nEftirbruninn (EPOC), aukin súrefnisnotkun eftir æfingu, er þó hóflegur: yfirleitt um 6–15% af orkunni sem æfingin sjálf brenndi. Fitutap ræðst fyrst og fremst af heildarorkujafnvægi yfir vikur og mánuði. Raunverulegi ávinningurinn af styrk er betri blóðsykurstjórn, sterkari líkami og betri færni – ekki „ofurbrennsla“.", "refs": ["Phillips o.fl., Am J Physiol 1997", "LaForgia o.fl., J Sports Sci 2006"]}, {"layout": "stat", "title": "Hvíldarbrennsla vöðva", "stat": "~13 kcal", "caption": "á kíló af vöðva á sólarhring í hvíld – um 4,5 kcal fyrir fitu", "body": "Vöðvi brennir um þrefalt meira en fita í hvíld. Tvö aukakíló af vöðva auka þó hvíldarbrennslu aðeins um 25–30 hitaeiningar á dag. Það er gott, en ekki kraftaverk. Vöðvarnir vinna mest fyrir þig þegar þeir eru notaðir: við hreyfingu, við að taka upp blóðsykur og við að halda þér færum um að lifa virku lífi.", "refs": ["Wang o.fl., Am J Clin Nutr 2010"]}, {"layout": "bullets", "title": "Stóru fjölliðaæfingarnar", "body": "Fjölliðaæfingar hreyfa marga liði og stóra vöðvahópa í einu. Þær gefa mikið fyrir tímann og líkjast hreyfingum daglegs lífs.", "items": ["Hnébeygja eða að setjast og standa upp af kassa – læri og rass", "Mjaðmalyfta eða réttstöðulyfta með léttri þyngd – aftanverð læri, rass og bak", "Pressa: armbeygjur (má gera við vegg eða borð) eða handlóðapressa", "Tog: róður með handlóði, teygju eða í tæki", "Framstig eða uppstig á pall – jafnvægi og styrkur í hvorum fæti", "Burður: að ganga með þung lóð í höndum styrkir grip og búk"], "refs": ["ACSM, Med Sci Sports Exerc 2009"]}, {"layout": "text", "title": "„Þungt og krefjandi“ – hvað þýðir það?", "body": "Vöðvar stækka og styrkjast þegar þeir fá áreiti sem er meira en þeir eru vanir. Þetta kallast stigvaxandi álag.\n\nÞungt þarf ekki að þýða gríðarlegar þyngdir. Safngreining sýndi að léttari þyngdir með fleiri endurtekningum byggja upp álíka mikinn vöðvamassa og þungar – svo lengi sem settin eru krefjandi. Þyngri lóð skila þó heldur meiri styrk. Lykillinn er áreynslan, ekki talan á lóðinu.", "refs": ["Schoenfeld o.fl., J Strength Cond Res 2017", "ACSM, Med Sci Sports Exerc 2009"]}, {"layout": "bullets", "title": "RIR: endurtekningar í varasjóði", "body": "RIR (e. repetitions in reserve) er einfaldur mælikvarði: hversu margar endurtekningar gætir þú gert í viðbót með góðri tækni?", "items": ["RIR 3–4: hæfilegt fyrir byrjendur og fyrstu vikurnar", "RIR 1–3: markmiðið þegar tæknin er orðin örugg", "Ekki þarf að fara alla leið í þrot – það skilar litlu eða engu aukalega", "Hættu settinu ef tæknin fer að bila, jafnvel þótt þú eigir endurtekningar eftir", "Skráðu RIR í dagbókina – það hjálpar þér að vita hvenær má þyngja"], "refs": ["Helms o.fl., Strength Cond J 2016", "Refalo o.fl., Sports Med 2023"]}, {"layout": "bullets", "title": "Stigvaxandi álag í framkvæmd", "body": "Einföld aðferð er „tvöföld framvinda“: fyrst fjölgar þú endurtekningum, síðan þyngir þú.", "items": ["Veldu bil, t.d. 8–12 endurtekningar, og þyngd sem gefur RIR um 2–3", "Þegar þú nærð 12 í öllum settum með góðri tækni: þyngdu um 2–10%", "Endurtekningum fækkar þá aftur og þú byrjar að vinna þig upp", "Án lóða: hægari hreyfing, lengri kyrrstaða eða erfiðari útgáfa æfingar", "Breyttu einu atriði í einu og gefðu líkamanum viku til að aðlagast"], "refs": ["ACSM, Med Sci Sports Exerc 2009"]}, {"layout": "text", "title": "Prótein fyrir viðgerð og uppbyggingu", "body": "Vöðvarnir byggjast upp úr próteini sem þú borðar. Í safngreiningu 49 rannsókna jók prótein ávinning af styrktarþjálfun, en ávinningurinn virtist ekki aukast að ráði umfram um 1,6 g á hvert kíló líkamsþyngdar á dag.\n\nHagnýtt: hafðu próteingjafa í hverri máltíð, t.d. fisk, skyr, egg, kjöt, baunir eða linsur. Ef þú ert með nýrnasjúkdóm skaltu ræða próteinmagn við lækni.", "refs": ["Morton o.fl., Br J Sports Med 2018"]}, {"layout": "tip", "title": "Ráð vikunnar", "body": "Taktu styrktaræfingar að minnsta kosti tvo daga í viku, eins og WHO mælir með – þetta kerfi gefur þér þrjá. Skrifaðu niður æfingu, þyngd, endurtekningar og RIR. Eftir fjórar vikur sérðu svart á hvítu að þú hefur styrkst. Sú tilfinning er einn besti hvatinn til að halda áfram.", "refs": ["Bull o.fl. (WHO), Br J Sports Med 2020"]}, {"layout": "bullets", "title": "Öryggi fyrst", "body": "Styrktarþjálfun hentar flestum, en sumir ættu að ræða við lækni áður en þeir byrja eða auka álag.", "items": ["Hjartasjúkdómur, brjóstverkur eða óútskýrð mæði við áreynslu", "Háþrýstingur – forðastu að halda niðri í þér andanum við átak", "Meðganga eða nýleg fæðing", "Nýleg aðgerð, beinþynning eða áverki", "Andaðu frá þér í átakinu og hættu ef þú finnur skarpan verk eða svima"]}, {"layout": "sources", "title": "Heimildir", "body": "Helstu heimildir sem fyrirlesturinn byggir á.", "items": ["DeFronzo RA, Tripathy D (2009). Skeletal muscle insulin resistance is the primary defect in type 2 diabetes. Diabetes Care, 32(Suppl 2), S157–S163. doi:10.2337/dc09-S302 / PMID 19875544", "Srikanthan P, Karlamangla AS (2011). Relative muscle mass is inversely associated with insulin resistance and prediabetes. Findings from the third National Health and Nutrition Examination Survey. J Clin Endocrinol Metab, 96(9), 2898–2903. doi:10.1210/jc.2011-0435 / PMID 21778224", "Momma H, Kawakami R, Honda T, Sawada SS (2022). Muscle-strengthening activities are associated with lower risk and mortality in major non-communicable diseases: a systematic review and meta-analysis of cohort studies. Br J Sports Med, 56(13), 755–763. doi:10.1136/bjsports-2021-105061 / PMID 35228201", "Umpierre D, Ribeiro PA, Kramer CK, Leitão CB o.fl. (2011). Physical activity advice only or structured exercise training and association with HbA1c levels in type 2 diabetes: a systematic review and meta-analysis. JAMA, 305(17), 1790–1799. doi:10.1001/jama.2011.576 / PMID 21540423", "Wewege MA, Desai I, Honey C, Coorie B o.fl. (2022). The effect of resistance training in healthy adults on body fat percentage, fat mass and visceral fat: a systematic review and meta-analysis. Sports Med, 52(2), 287–300. doi:10.1007/s40279-021-01562-2 / PMID 34536199", "Ismail I, Keating SE, Baker MK, Johnson NA (2012). A systematic review and meta-analysis of the effect of aerobic vs. resistance exercise training on visceral fat. Obes Rev, 13(1), 68–91. doi:10.1111/j.1467-789X.2011.00931.x / PMID 21951360", "Phillips SM, Tipton KD, Aarsland A, Wolf SE, Wolfe RR (1997). Mixed muscle protein synthesis and breakdown after resistance exercise in humans. Am J Physiol, 273(1 Pt 1), E99–E107. doi:10.1152/ajpendo.1997.273.1.E99 / PMID 9252485", "LaForgia J, Withers RT, Gore CJ (2006). Effects of exercise intensity and duration on the excess post-exercise oxygen consumption. J Sports Sci, 24(12), 1247–1264. doi:10.1080/02640410600552064 / PMID 17101527", "Wang Z, Ying Z, Bosy-Westphal A, Zhang J o.fl. (2010). Specific metabolic rates of major organs and tissues across adulthood: evaluation by mechanistic model of resting energy expenditure. Am J Clin Nutr, 92(6), 1369–1377. doi:10.3945/ajcn.2010.29885 / PMID 20962155", "American College of Sports Medicine (2009). American College of Sports Medicine position stand. Progression models in resistance training for healthy adults. Med Sci Sports Exerc, 41(3), 687–708. doi:10.1249/MSS.0b013e3181915670 / PMID 19204579", "Schoenfeld BJ, Grgic J, Ogborn D, Krieger JW (2017). Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis. J Strength Cond Res, 31(12), 3508–3523. doi:10.1519/JSC.0000000000002200 / PMID 28834797", "Helms ER, Cronin J, Storey A, Zourdos MC (2016). Application of the repetitions in reserve-based rating of perceived exertion scale for resistance training. Strength Cond J, 38(4), 42–49. doi:10.1519/SSC.0000000000000218 / PMID 27531969", "Refalo MC, Helms ER, Trexler ET, Hamilton DL o.fl. (2023). Influence of resistance training proximity-to-failure on skeletal muscle hypertrophy: a systematic review with meta-analysis. Sports Med, 53(3), 649–665. doi:10.1007/s40279-022-01784-y / PMID 36334240", "Morton RW, Murphy KT, McKellar SR, Schoenfeld BJ o.fl. (2018). A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults. Br J Sports Med, 52(6), 376–384. doi:10.1136/bjsports-2017-097608 / PMID 28698222", "Bull FC, Al-Ansari SS, Biddle S, Borodulin K o.fl. (2020). World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med, 54(24), 1451–1462. doi:10.1136/bjsports-2020-102955 / PMID 33239350"]}]'::jsonb, 15, 'exercise', false, 21, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('hreyfing-hiit-stutt-og-akaft', 'HIIT: stutt og ákaft', 'Hvað lotuþjálfun gerir fyrir þol, blóðsykur og kviðfitu – og hvernig þú gerir hana á öruggan hátt', 'slides', '[{"layout": "stat", "title": "Sami árangur – minni tími", "stat": "~40%", "caption": "minni æfingatími í HIIT en í jafnri þolþjálfun, með sambærilegum áhrifum á líkamsfitu", "body": "Tímaleysi er ein algengasta ástæðan fyrir því að fólk hreyfir sig ekki. Lotuþjálfun (HIIT) er ein leið til að fá mikið út úr stuttum tíma. Í samantekt rannsókna á fólki í yfirþyngd skiluðu HIIT og jöfn þolþjálfun svipaðri minnkun á fitu og mittismáli, en HIIT tók um 40% minni tíma.", "refs": ["Wewege o.fl., Obes Rev 2017"]}, {"layout": "text", "title": "Hvað er HIIT?", "body": "HIIT (e. high-intensity interval training) eru stuttar, krefjandi lotur með hléum á milli. Í átakslotunni er andardrátturinn þungur og þú getur aðeins sagt stök orð – um 8 af 10 á áreynslukvarða. Í hléinu nærðu andanum aftur.\n\nLoturnar geta verið frá 20 sekúndum upp í 4 mínútur. Hjól, hlaup, róður, rösk ganga upp brekku eða líkamsæfingar henta öll. Það sem skiptir máli er áreynslan miðað við þína eigin getu, ekki hraðinn hjá öðrum.", "refs": ["Weston o.fl., Br J Sports Med 2014"]}, {"layout": "text", "title": "Hvað gerist í líkamanum?", "body": "Í hverri lotu vinnur hjartað nálægt hámarksgetu. Endurtekið áreiti styrkir hjartavöðvann og eykur blóðflæði til vöðvanna.\n\nÍ vöðvunum fjölgar hvatberum, „orkuverum“ frumnanna, og vöðvarnir ganga á glýkógenforðann. Til að fylla á hann aftur taka þeir upp sykur úr blóðinu. Í einni rannsókn jókst insúlínnæmi og hvatberamagn álíka mikið eftir 10 mínútna lotuþjálfun, þar af 1 mínútu af hámarksátaki, og eftir 50 mínútna jafna þjálfun.", "refs": ["Gillen o.fl., PLoS One 2016"]}, {"layout": "stat", "title": "Þol er öflugur heilsumælikvarði", "stat": "13%", "caption": "minni dánartíðni fyrir hverja einingu (1 MET) betra þols", "body": "Samantekt 33 hóprannsókna með yfir 100.000 þátttakendum sýndi að betra þol tengdist minni áhættu á ótímabærum dauða og hjarta- og æðasjúkdómum. Ein MET-eining samsvarar um 1 km/klst. hraðara hlaupi. Þetta eru tengsl, en þol er einn sterkasti heilsumælikvarði sem við þekkjum – og hann er hægt að bæta.", "refs": ["Kodama o.fl., JAMA 2009"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "HIIT hefur verið borið saman við jafna þolþjálfun í fjölda rannsókna.", "items": ["39 rannsóknir: HIIT minnkaði heildarfitu, kviðfitu og innyflafitu", "Í fólki í yfirþyngd var enginn marktækur munur á fitutapi milli HIIT og jafnrar þjálfunar", "50 rannsóknir: HIIT dró úr insúlínviðnámi, bæði miðað við enga þjálfun og jafna þjálfun", "Hjá fólki með lífsstílstengda sjúkdóma jók HIIT hámarkssúrefnisupptöku nær tvöfalt meira", "Hjá hraustu fólki bæta báðar aðferðir þol vel"], "refs": ["Maillard o.fl., Sports Med 2018", "Wewege o.fl., Obes Rev 2017", "Jelleyman o.fl., Obes Rev 2015", "Weston o.fl., Br J Sports Med 2014", "Milanović o.fl., Sports Med 2015"]}, {"layout": "text", "title": "HIIT eða jöfn hreyfing?", "body": "Svarið er: bæði. Fyrir fitutap virðast aðferðirnar álíka góðar – HIIT sparar fyrst og fremst tíma. Fyrir þol og insúlínnæmi hefur HIIT oft örlítið forskot.\n\nAthyglisvert er að í safngreiningu Maillard og félaga tengdist álag undir 90% af hámarkspúlsi meiri minnkun á kvið- og innyflafitu, og hlaup skilaði meiru en hjólreiðar. Besta æfingin er sú sem þú stundar reglulega, og dagleg ganga bætist við HIIT, hún kemur ekki í staðinn.", "refs": ["Maillard o.fl., Sports Med 2018", "Wewege o.fl., Obes Rev 2017", "Jelleyman o.fl., Obes Rev 2015"]}, {"layout": "text", "title": "Adrenalín og vaxtarhormón – hvað er satt?", "body": "Við HIIT hækka streituhormón á borð við adrenalín og noradrenalín, og vaxtarhormón hækkar tímabundið. Ein tilgáta er að adrenalínið losi meiri fitu úr fituvef, en það er enn tilgáta.\n\nStór rannsókn sýndi að tímabundnar hormónasveiflur eftir æfingu spáðu ekki fyrir um vöðvavöxt eða styrk. Hormónin eru því ekki leyndarmálið. Ávinningurinn kemur frá endurtekinni þjálfun yfir vikur og mánuði.", "refs": ["Boutcher, J Obes 2011", "West & Phillips, Eur J Appl Physiol 2012"]}, {"layout": "text", "title": "Eftirbruninn – minni en sagt er", "body": "Oft er sagt að HIIT „brenni í allan dag“. Líkaminn notar vissulega meiri orku eftir krefjandi æfingu (EPOC), en rannsóknir sýna að þessi aukabrennsla er yfirleitt aðeins um 6–15% af orkunni sem æfingin sjálf brenndi.\n\nSæktu því ekki í HIIT vegna eftirbrunans. Sæktu í það vegna þess að það bætir þol og blóðsykurstjórn á stuttum tíma.", "refs": ["LaForgia o.fl., J Sports Sci 2006"]}, {"layout": "bullets", "title": "Uppbygging æfingar: 10–20 mínútur", "body": "Svona gæti dæmigerð HIIT-æfing litið út, þrisvar í viku með hvíldardegi á milli:", "items": ["Upphitun: 3–5 mínútur af rólegri hreyfingu sem eykst smám saman", "Byrjendur: 30 sekúndna átak + 90 sekúndur rólegt, 4–6 sinnum", "Lengra komnir: 1 mínútu átak + 1 mínúta rólegt, 6–10 sinnum", "Niðurlag: 3 mínútur af rólegri hreyfingu", "Ekki fleiri en þrjár HIIT-æfingar í viku – hvíldin er hluti af þjálfuninni"], "refs": ["Gillen o.fl., PLoS One 2016", "Wewege o.fl., Obes Rev 2017"]}, {"layout": "bullets", "title": "Hversu fast? Notaðu áreynslukvarðann", "body": "Þú þarft ekki púlsmæli. Áreynslukvarði frá 0 upp í 10 dugar vel:", "items": ["3–4: rólegt – þú getur spjallað (upphitun og hlé)", "6: nokkuð erfitt – stuttar setningar", "7–8: erfitt – aðeins stök orð (flestar átakslotur)", "9: mjög erfitt – fyrir lengra komna, stuttar lotur", "Fyrstu 4 vikurnar: haltu þig við 6–7"]}, {"layout": "stat", "title": "Er HIIT öruggt?", "stat": "1 á 23.182 klst.", "caption": "tíðni hjartastopps við HIIT hjá hjartasjúklingum í eftirlitsþjálfun (1 á 129.456 klst. í hóflegri þjálfun)", "body": "Norsk rannsókn á 4.846 hjartasjúklingum í endurhæfingu fann að áhætta var lítil í báðum tegundum þjálfunar, en heldur meiri við mikið álag. Þetta var undir eftirliti fagfólks. Hjá hraustu fólki er áhættan enn minni, en það borgar sig að byrja rólega og hlusta á líkamann.", "refs": ["Rognmo o.fl., Circulation 2012"]}, {"layout": "bullets", "title": "Ræddu við lækni fyrst ef …", "body": "HIIT hentar flestum, en sumir ættu að fá grænt ljós frá lækni áður en þeir byrja:", "items": ["Þú ert með hjartasjúkdóm, hjartsláttartruflanir eða háan blóðþrýsting sem er ekki í jafnvægi", "Þú hefur fengið brjóstverk, yfirlið eða mikla mæði við áreynslu", "Þú notar insúlín eða lyf sem geta valdið blóðsykursfalli", "Þú ert barnshafandi", "Hættu strax ef þú færð brjóstverk, svima eða óeðlilegan hjartslátt"]}, {"layout": "tip", "title": "Byrjaðu mjúkt", "body": "Fyrstu fjórar vikurnar í kerfinu eru aðlögunartímabil. Þá eru loturnar færri og styttri og átakið hóflegt. Það er meðvitað. Hjarta, vöðvar og liðir fá tíma til að venjast. Ef lotu-hopp fara illa í hnén skaltu velja hjól, róður eða rösklega göngu upp brekku. Það er átakið sem telur, ekki æfingin sjálf."}, {"layout": "sources", "title": "Heimildir", "body": "Helstu heimildir sem fyrirlesturinn byggir á.", "items": ["Wewege M, van den Berg R, Ward RE, Keech A (2017). The effects of high-intensity interval training vs. moderate-intensity continuous training on body composition in overweight and obese adults: a systematic review and meta-analysis. Obes Rev, 18(6), 635–646. doi:10.1111/obr.12532 / PMID 28401638", "Maillard F, Pereira B, Boisseau N (2018). Effect of high-intensity interval training on total, abdominal and visceral fat mass: a meta-analysis. Sports Med, 48(2), 269–288. doi:10.1007/s40279-017-0807-y / PMID 29127602", "Jelleyman C, Yates T, O''Donovan G, Gray LJ o.fl. (2015). The effects of high-intensity interval training on glucose regulation and insulin resistance: a meta-analysis. Obes Rev, 16(11), 942–961. doi:10.1111/obr.12317 / PMID 26481101", "Weston KS, Wisløff U, Coombes JS (2014). High-intensity interval training in patients with lifestyle-induced cardiometabolic disease: a systematic review and meta-analysis. Br J Sports Med, 48(16), 1227–1234. doi:10.1136/bjsports-2013-092576 / PMID 24144531", "Milanović Z, Sporiš G, Weston M (2015). Effectiveness of high-intensity interval training (HIT) and continuous endurance training for VO2max improvements: a systematic review and meta-analysis of controlled trials. Sports Med, 45(10), 1469–1481. doi:10.1007/s40279-015-0365-0 / PMID 26243014", "Gillen JB, Martin BJ, MacInnis MJ, Skelly LE o.fl. (2016). Twelve weeks of sprint interval training improves indices of cardiometabolic health similar to traditional endurance training despite a five-fold lower exercise volume and time commitment. PLoS One, 11(4), e0154075. doi:10.1371/journal.pone.0154075 / PMID 27115137", "Kodama S, Saito K, Tanaka S, Maki M o.fl. (2009). Cardiorespiratory fitness as a quantitative predictor of all-cause mortality and cardiovascular events in healthy men and women: a meta-analysis. JAMA, 301(19), 2024–2035. doi:10.1001/jama.2009.681 / PMID 19454641", "Boutcher SH (2011). High-intensity intermittent exercise and fat loss. J Obes, 2011, 868305. doi:10.1155/2011/868305 / PMID 21113312", "West DW, Phillips SM (2012). Associations of exercise-induced hormone profiles and gains in strength and hypertrophy in a large cohort after weight training. Eur J Appl Physiol, 112(7), 2693–2702. doi:10.1007/s00421-011-2246-z / PMID 22105707", "LaForgia J, Withers RT, Gore CJ (2006). Effects of exercise intensity and duration on the excess post-exercise oxygen consumption. J Sports Sci, 24(12), 1247–1264. doi:10.1080/02640410600552064 / PMID 17101527", "Rognmo Ø, Moholdt T, Bakken H, Hole T o.fl. (2012). Cardiovascular risk of high- versus moderate-intensity aerobic exercise in coronary heart disease patients. Circulation, 126(12), 1436–1440. doi:10.1161/CIRCULATIONAHA.112.123117 / PMID 22879367"]}]'::jsonb, 14, 'exercise', false, 22, true)
