  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('hreyfing-ad-byrja-rett', 'Að byrja rétt: aðlögun, álag og meiðsli', 'Af hverju fyrstu vikurnar skipta mestu, hvernig þú lest í líkamann og hvernig þú æfir í kringum eymsli', 'slides', '[{"layout": "quote", "title": "Leiðarljósið", "body": "„Byrjaðu hægar en þér finnst þú þurfa – og haltu lengur áfram en þér finnst þú geta.“", "caption": "Heilræði Lifeline"}, {"layout": "text", "title": "Vöðvar eru fljótari en sinar", "body": "Fyrstu vikurnar eykst styrkur hratt, einkum vegna þess að taugakerfið lærir að virkja vöðvana betur. Vöðvarnir fylgja svo á eftir.\n\nSinar og bandvefur aðlagast hægar. Endurnýjun kollagens í sinum er hæg og sinar þurfa töluvert álag yfir lengri tíma til að styrkjast. Þá myndast bil: þú getur lyft meiru en sinarnar eru tilbúnar fyrir. Þar liggja mörg álagsmeiðsli.", "refs": ["Magnusson & Kjaer, J Physiol 2019", "Bohm o.fl., Sports Med Open 2015"]}, {"layout": "stat", "title": "Sinar þurfa tíma", "stat": "12+ vikur", "caption": "Sinar styrktust mest í rannsóknum sem stóðu í 12 vikur eða lengur, með nokkuð miklu álagi", "body": "Í samantekt 27 rannsókna á heilbrigðum fullorðnum jókst stífleiki og styrkur sina við reglulegt álag. Áhrifin voru háð álaginu og virtust meiri eftir lengri tíma. Sinar þola því álag vel – en þær vilja fá það jafnt og þétt, ekki allt í einu.", "refs": ["Bohm o.fl., Sports Med Open 2015"]}, {"layout": "text", "title": "Af hverju fjögurra vikna aðlögun?", "body": "Byrjendur í þessu kerfi fá fjögurra vikna aðlögunartímabil. Það hefur þrjá tilgangi:\n\nAð læra tæknina á meðan þyngdirnar eru léttar. Að gefa sinum, liðum og bandvef forskot. Og að byggja upp vana – sem skiptir meira máli en nokkur ein æfing.\n\nÞér gæti fundist þetta of létt. Það er í lagi. Þú byggir grunn sem ber álagið sem kemur síðar.", "refs": ["Magnusson & Kjaer, J Physiol 2019", "ACSM, Med Sci Sports Exerc 2009"]}, {"layout": "bullets", "title": "RPE og RIR – innri mælikvarðinn", "body": "Sama þyngd getur verið létt einn daginn og erfið þann næsta, eftir svefni, streitu og næringu. Þess vegna stýrum við álagi eftir líðan:", "items": ["RPE: hversu erfitt var þetta á kvarðanum 0–10?", "RIR: hversu margar endurtekningar áttir þú eftir?", "Aðlögunartímabil: RPE 5–7 eða RIR 3–4", "Eftir aðlögun: RPE 7–9 eða RIR 1–3", "Á slæmum degi: léttu þyngdina en haltu í taktinn"], "refs": ["Helms o.fl., Strength Cond J 2016"]}, {"layout": "bullets", "title": "Álagsstjórnun í reynd", "body": "Stigvaxandi álag þarf ekki að vera flókið. Nokkrar einfaldar reglur duga langt:", "items": ["Breyttu einu atriði í einu: þyngd, endurtekningum, settum eða hraða", "Þyngdu þegar efri mörk endurtekninga nást með RIR 2 eða meira", "Hófleg aukning í senn, t.d. 2–10% í þyngd", "Á nokkurra vikna fresti: léttari vika til að ná upp orku", "Eftir veikindi eða frí: byrjaðu léttar og byggðu upp aftur á 1–2 vikum"], "refs": ["ACSM, Med Sci Sports Exerc 2009"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Styrkur er ekki bara áhætta – hann er líka vörn og meðferð.", "items": ["25 slembirannsóknir: styrktarþjálfun minnkaði íþróttameiðsli niður í innan við þriðjung", "Teygjur einar og sér drógu ekki úr meiðslum", "249 rannsóknir: æfingar draga líklega úr verkjum í langvinnum mjóbaksverk", "139 rannsóknir: æfingar tengjast minni verkjum og betri færni við slitgigt í hné", "Hófleg áreynsla með verkjavöktun skaðaði ekki bata í sinavandamáli"], "refs": ["Lauersen o.fl., Br J Sports Med 2014", "Hayden o.fl., Cochrane 2021", "Lawford o.fl., Cochrane 2024", "Silbernagel o.fl., Am J Sports Med 2007"]}, {"layout": "bullets", "title": "Verkjareglan: umferðarljósið", "body": "Í endurhæfingu er oft notuð verkjavöktun. Metið verkinn á kvarðanum 0–10 meðan á æfingu stendur og daginn eftir:", "items": ["Grænt (0–2): haltu áfram eins og áætlað er", "Gult (3–5): ásættanlegt ef verkurinn hjaðnar fyrir næsta morgun", "Rautt (yfir 5): minnkaðu álag, styttu hreyfiferil eða skiptu um æfingu", "Verkur eða stirðleiki sem eykst viku frá viku er merki um að draga úr", "Skarpur, stingandi verkur: hættu æfingunni"], "refs": ["Silbernagel o.fl., Am J Sports Med 2007"]}, {"layout": "text", "title": "Harðsperrur eða meiðsli?", "body": "Harðsperrur koma gjarnan 1–2 sólarhringum eftir nýja eða erfiða æfingu. Þær eru dreifður, aumur verkur í vöðvanum, beggja vegna, og minnka á nokkrum dögum. Þær minnka líka eftir því sem þú venst.\n\nMeiðsli eru oftar staðbundin, á annarri hliðinni, í lið eða sin, geta komið skyndilega og versna við ákveðnar hreyfingar. Bólga, mar eða skert hreyfigeta eru líka merki um að eitthvað annað sé á ferðinni."}, {"layout": "bullets", "title": "Öxl: æfðu í kringum eymslin", "body": "Kerfið skiptir sjálfkrafa út æfingum ef þú merkir við öxl. Algengar leiðir:", "items": ["Veldu hlutlaust grip (lófar snúa hvor að öðrum) í pressum", "Armbeygjur við borð eða vegg í stað pressu yfir höfuð", "Fleiri togæfingar (róður) en pressur – styrkir herðablöðin", "Vinndu á sársaukalausu hreyfisviði og stækkaðu það smám saman", "Léttar teygjuæfingar fyrir snúningsvöðva axlarinnar"]}, {"layout": "bullets", "title": "Hné: styrkur er oft hluti lausnarinnar", "body": "Hjá fólki með slitgigt í hné tengjast æfingar minni verkjum og betri færni. Algengar breytingar:", "items": ["Hnébeygja niður á kassa eða stól – stilltu hæðina eftir líðan", "Styttra hreyfisvið í framstigi og uppstigi á lágan pall", "Mjaðmalyfta og æfingar fyrir aftanverð læri reyna minna á hnéð", "Hjól eða róður í stað hoppa og hlaupa í HIIT", "Hnéð má fara fram fyrir tærnar – ef það er sársaukalaust"], "refs": ["Lawford o.fl., Cochrane 2024"]}, {"layout": "bullets", "title": "Bak: hreyfing er yfirleitt betri en hvíld", "body": "Við langvinnum mjóbaksverk benda rannsóknir til þess að æfingar dragi úr verkjum. Góðar leiðir:", "items": ["Lærðu mjaðmabeygju með priki eða léttu lóði áður en þú þyngir", "Spenntu kviðinn létt og andaðu – ekki halda niðri í þér andanum", "Fuglahundur, hliðarplanki og mjaðmalyfta byggja upp búkstyrk", "Veldu handlóð eða ketilbjöllu í stað þungrar stangar til að byrja með", "Dagleg ganga styður við bakið"], "refs": ["Hayden o.fl., Cochrane 2021"]}, {"layout": "bullets", "title": "Hvenær á að leita til fagfólks?", "body": "Leitaðu til sjúkraþjálfara ef verkur lagast ekki á 2–3 vikum þrátt fyrir breytingar. Leitaðu strax til læknis ef:", "items": ["Þú færð brjóstverk, yfirlið eða mikla mæði við áreynslu", "Dofi kemur í klof eða þú missir stjórn á þvagi eða hægðum", "Máttleysi eða dofi breiðist út í fót eða handlegg", "Verkur fylgir hita, óútskýrðu þyngdartapi eða kemur eftir slys", "Liður bólgnar mikið, læsist eða gefur eftir"]}, {"layout": "tip", "title": "Haltu æfingadagbók", "body": "Skráðu í hverri æfingu: æfingu, þyngd, endurtekningar, RIR og verk á kvarðanum 0–10. Á tveimur mínútum færðu mynd sem sýnir hvort þú ert á réttri leið – og hvort tiltekin æfing er farin að erta. Dagbókin er líka besta gagnið sem þú getur tekið með til sjúkraþjálfara eða læknis."}, {"layout": "sources", "title": "Heimildir", "body": "Helstu heimildir sem fyrirlesturinn byggir á.", "items": ["Magnusson SP, Kjaer M (2019). The impact of loading, unloading, ageing and injury on the human tendon. J Physiol, 597(5), 1283–1298. doi:10.1113/JP275450 / PMID 29920664", "Bohm S, Mersmann F, Arampatzis A (2015). Human tendon adaptation in response to mechanical loading: a systematic review and meta-analysis of exercise intervention studies on healthy adults. Sports Med Open, 1(1), 7. doi:10.1186/s40798-015-0009-9 / PMID 27747846", "American College of Sports Medicine (2009). American College of Sports Medicine position stand. Progression models in resistance training for healthy adults. Med Sci Sports Exerc, 41(3), 687–708. doi:10.1249/MSS.0b013e3181915670 / PMID 19204579", "Helms ER, Cronin J, Storey A, Zourdos MC (2016). Application of the repetitions in reserve-based rating of perceived exertion scale for resistance training. Strength Cond J, 38(4), 42–49. doi:10.1519/SSC.0000000000000218 / PMID 27531969", "Lauersen JB, Bertelsen DM, Andersen LB (2014). The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials. Br J Sports Med, 48(11), 871–877. doi:10.1136/bjsports-2013-092538 / PMID 24100287", "Hayden JA, Ellis J, Ogilvie R, Malmivaara A, van Tulder MW (2021). Exercise therapy for chronic low back pain. Cochrane Database Syst Rev, 9(9), CD009790. doi:10.1002/14651858.CD009790.pub2 / PMID 34580864", "Lawford BJ, Hall M, Hinman RS, Van der Esch M o.fl. (2024). Exercise for osteoarthritis of the knee. Cochrane Database Syst Rev, 12(12), CD004376. doi:10.1002/14651858.CD004376.pub4 / PMID 39625083", "Silbernagel KG, Thomeé R, Eriksson BI, Karlsson J (2007). Continued sports activity, using a pain-monitoring model, during rehabilitation in patients with Achilles tendinopathy: a randomized controlled study. Am J Sports Med, 35(6), 897–906. doi:10.1177/0363546506298279 / PMID 17307888"]}]'::jsonb, 14, 'exercise', false, 23, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('hreyfing-kuldi-dagleg-hreyfing-kyrrseta', 'Kuldi, dagleg hreyfing og kyrrseta', 'Skrefin sem telja, af hverju það skiptir máli að standa upp – og hvað við vitum í raun um kuldann', 'slides', '[{"layout": "stat", "title": "Hvert skref telur", "stat": "40%", "caption": "lægri dánartíðni hjá þeim sem gengu um 5.800 skref á dag miðað við um 3.500 skref", "body": "Samantekt 15 hóprannsókna með um 47.000 fullorðnum sýndi að fleiri dagleg skref tengdust minni áhættu á ótímabærum dauða. Stærsti munurinn var á milli þeirra sem gengu minnst og næsta hóps. Þetta eru tengsl úr hóprannsóknum, en þau eru skýr og samræmd.", "refs": ["Paluch o.fl., Lancet Public Health 2022"]}, {"layout": "text", "title": "Hversu mörg skref þarf?", "body": "Tíu þúsund skref eru ekki töfratala. Í sömu rannsókn minnkaði áhættan eftir því sem skrefunum fjölgaði, en jafnaðist út:\n\nHjá 60 ára og eldri við um 6.000–8.000 skref á dag. Hjá yngri en 60 ára við um 8.000–10.000 skref á dag.\n\nEf þú gengur 3.000 skref í dag er markmiðið ekki 10.000 á morgun. Bættu við 1.000 skrefum í einu og haltu því í viku eða tvær.", "refs": ["Paluch o.fl., Lancet Public Health 2022"]}, {"layout": "text", "title": "Kyrrseta er sjálfstæður áhættuþáttur", "body": "Samantekt á gögnum yfir milljón manna sýndi að þeir sem sátu meira en 8 klukkustundir á dag og hreyfðu sig lítið höfðu 59% hærri dánartíðni en þeir sem sátu minna og hreyfðu sig mest.\n\nGóðu fréttirnar: hjá þeim sem hreyfðu sig mest, um 60–75 mínútur af hóflegri hreyfingu á dag, sáust ekki þessi tengsl. Mikil hreyfing virðist geta vegið upp á móti setunni.", "refs": ["Ekelund o.fl., Lancet 2016"]}, {"layout": "stat", "title": "Tvær mínútur geta skipt máli", "stat": "2 / 20 mín.", "caption": "stuttir göngutúrar á 20 mínútna fresti lækkuðu blóðsykurstopp eftir máltíð um fjórðung", "body": "Í tilraun með 19 fullorðnum í yfirþyngd sátu þátttakendur í 5 klukkustundir eftir sykraðan drykk. Þegar þeir stóðu upp og gengu í 2 mínútur á 20 mínútna fresti var blóðsykur- og insúlínhækkunin um fjórðungi minni en þegar þeir sátu samfellt.", "refs": ["Dunstan o.fl., Diabetes Care 2012"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Um daglega hreyfingu og setu er þekkingin nokkuð traust:", "items": ["WHO mælir með 150–300 mínútum af hóflegri hreyfingu á viku – og að draga úr kyrrsetu", "WHO: öll hreyfing telur, líka stuttar lotur", "Stuttar gönguferðir til að brjóta upp setu lækkuðu blóðsykur og insúlín meira en að standa", "Að standa upp er samt betra en að sitja samfellt", "Fleiri dagleg skref tengjast minni dánartíðni, upp að ákveðnu marki"], "refs": ["Bull o.fl. (WHO), Br J Sports Med 2020", "Buffey o.fl., Sports Med 2022", "Paluch o.fl., Lancet Public Health 2022"]}, {"layout": "bullets", "title": "Brjóttu upp daginn", "body": "Litlar venjur yfir daginn safnast saman. Veldu tvær eða þrjár sem henta þínum vinnudegi:", "items": ["Stattu upp og gakktu í 2–3 mínútur á 30 mínútna fresti – stilltu áminningu", "Taktu símtöl gangandi eða standandi", "Stuttur göngutúr eftir hádegismat og kvöldmat", "Stigar í stað lyftu, og leggðu bílnum aðeins lengra frá", "Göngufundir fyrir styttri samtöl", "Vatnsglas á borðinu – áfyllingin kallar á hreyfingu"], "refs": ["Dunstan o.fl., Diabetes Care 2012", "Buffey o.fl., Sports Med 2022"]}, {"layout": "text", "title": "Kuldi og brún fita – hvað er það?", "body": "Brún fita er sérstök tegund fituvefjar sem framleiðir hita í stað þess að geyma orku. Lengi var talið að aðeins ungbörn hefðu hana.\n\nÁrið 2009 sýndi rannsókn á 24 karlmönnum að flestir fullorðnir hafa virka brúna fitu þegar þeim er kalt, við um 16 °C. Virknin var minni hjá körlum í yfirþyngd. Síðan hefur verið kannað hvort kuldi geti aukið þessa virkni og haft áhrif á efnaskipti.", "refs": ["van Marken Lichtenbelt o.fl., NEJM 2009"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar um kulda?", "body": "Rannsóknirnar eru áhugaverðar, en litlar og flestar stuttar:", "items": ["2 klst. á dag við 17 °C í 6 vikur: brún fita jókst og fitumassi minnkaði lítillega", "10 dagar við 14–15 °C: insúlínnæmi jókst um 43% hjá 8 sjúklingum með sykursýki 2", "Þar skýrðust áhrifin einkum af vöðvunum, en brún fita skipti litlu", "Vetrarsundmenn brenndu meiri orku í kulda en samanburðarhópur", "Yfirlit 104 rannsókna: flestar smáar og ólíkar – áhrifin enn umdeild"], "refs": ["Yoneshiro o.fl., J Clin Invest 2013", "Hanssen o.fl., Nat Med 2015", "Søberg o.fl., Cell Rep Med 2021", "Espeland o.fl., Int J Circumpolar Health 2022"]}, {"layout": "text", "title": "Heiðarlegt mat: kuldi er aukaatriði", "body": "Fyrir hreyfingu og svefn höfum við stórar safngreiningar með hundruðum þúsunda þátttakenda. Fyrir kulda höfum við að mestu litlar rannsóknir, oft með færri en 20 manns.\n\nAthugaðu líka að mörg jákvæð áhrifin sáust eftir klukkustunda væga kælingu á dag, ekki tveggja mínútna kalda sturtu. Orkan sem brennur er hófleg. Kuldi getur verið hressandi viðbót, en hann kemur ekki í stað hreyfingar.", "refs": ["Espeland o.fl., Int J Circumpolar Health 2022", "Tipton o.fl., Exp Physiol 2017"]}, {"layout": "text", "title": "Kalda sturtan", "body": "Í hollenskri rannsókn voru 3.018 fullorðnir beðnir um að enda sturtuna á 30–90 sekúndum af köldu vatni í 30 daga. Hópurinn skráði 29% færri fjarvistir frá vinnu vegna veikinda, en veikindadögum sjálfum fækkaði ekki.\n\nÞátttakendur vissu í hvaða hópi þeir voru, sem getur haft áhrif á svörin. Ef þér líður vel eftir kalda sturtu er það gott – en væntu ekki of mikils.", "refs": ["Buijze o.fl., PLoS One 2016"]}, {"layout": "bullets", "title": "Öryggi í köldu vatni", "body": "Skyndileg dýfa í kalt vatn veldur „kuldaáfalli“: andköfum, hröðum andardrætti, hækkuðum blóðþrýstingi og auknu álagi á hjartað.", "items": ["Farðu aldrei án félaga í kalt vatn eða sjó", "Farðu hægt ofan í og haltu höfðinu upp úr fyrstu mínútuna", "Ekki áfengi fyrir eða eftir", "Stuttur tími dugar – kuldinn getur skert kraft og dómgreind", "Ræddu við lækni fyrst ef þú ert með hjartasjúkdóm eða háþrýsting, eða ef þú ert barnshafandi"], "refs": ["Tipton o.fl., Exp Physiol 2017"]}, {"layout": "tip", "title": "Kuldi og styrktaræfingar", "body": "Ef þú stundar kaldar sturtur eða sjósund skaltu ekki setja það beint eftir styrktaræfingu. Í rannsókn þar sem karlmenn fóru í kalt bað í 10 mínútur eftir hverja styrktaræfingu í 12 vikur jukust styrkur og vöðvamassi minna en hjá þeim sem hreyfðu sig rólega í staðinn. Hafðu kuldann á öðrum dögum eða með nokkurra klukkustunda millibili.", "refs": ["Roberts o.fl., J Physiol 2015"]}, {"layout": "bullets", "title": "Forgangsröðun", "body": "Ef þú hefur takmarkaðan tíma og orku, byrjaðu efst og vinndu þig niður:", "items": ["1. Dagleg hreyfing: skref og ganga – grunnurinn", "2. Styrkur og HIIT þrisvar í viku", "3. Brjóttu upp setuna á 30–60 mínútna fresti", "4. Svefn og næring sem styðja við þjálfunina", "5. Kuldi – valfrjáls viðbót ef þér líkar hann"], "refs": ["Bull o.fl. (WHO), Br J Sports Med 2020", "Paluch o.fl., Lancet Public Health 2022", "Ekelund o.fl., Lancet 2016"]}, {"layout": "sources", "title": "Heimildir", "body": "Helstu heimildir sem fyrirlesturinn byggir á.", "items": ["Paluch AE, Bajpai S, Bassett DR, Carnethon MR o.fl. (2022). Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts. Lancet Public Health, 7(3), e219–e228. doi:10.1016/S2468-2667(21)00302-9 / PMID 35247352", "Ekelund U, Steene-Johannessen J, Brown WJ, Fagerland MW o.fl. (2016). Does physical activity attenuate, or even eliminate, the detrimental association of sitting time with mortality? A harmonised meta-analysis of data from more than 1 million men and women. Lancet, 388(10051), 1302–1310. doi:10.1016/S0140-6736(16)30370-1 / PMID 27475271", "Dunstan DW, Kingwell BA, Larsen R, Healy GN o.fl. (2012). Breaking up prolonged sitting reduces postprandial glucose and insulin responses. Diabetes Care, 35(5), 976–983. doi:10.2337/dc11-1931 / PMID 22374636", "Buffey AJ, Herring MP, Langley CK, Donnelly AE, Carson BP (2022). The acute effects of interrupting prolonged sitting time in adults with standing and light-intensity walking on biomarkers of cardiometabolic health in adults: a systematic review and meta-analysis. Sports Med, 52(8), 1765–1787. doi:10.1007/s40279-022-01649-4 / PMID 35147898", "Bull FC, Al-Ansari SS, Biddle S, Borodulin K o.fl. (2020). World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med, 54(24), 1451–1462. doi:10.1136/bjsports-2020-102955 / PMID 33239350", "van Marken Lichtenbelt WD, Vanhommerig JW, Smulders NM, Drossaerts JM o.fl. (2009). Cold-activated brown adipose tissue in healthy men. N Engl J Med, 360(15), 1500–1508. doi:10.1056/NEJMoa0808718 / PMID 19357405", "Yoneshiro T, Aita S, Matsushita M, Kayahara T o.fl. (2013). Recruited brown adipose tissue as an antiobesity agent in humans. J Clin Invest, 123(8), 3404–3408. doi:10.1172/JCI67803 / PMID 23867622", "Hanssen MJ, Hoeks J, Brans B, van der Lans AA o.fl. (2015). Short-term cold acclimation improves insulin sensitivity in patients with type 2 diabetes mellitus. Nat Med, 21(8), 863–865. doi:10.1038/nm.3891 / PMID 26147760", "Søberg S, Löfgren J, Philipsen FE, Jensen M o.fl. (2021). Altered brown fat thermoregulation and enhanced cold-induced thermogenesis in young, healthy, winter-swimming men. Cell Rep Med, 2(10), 100408. doi:10.1016/j.xcrm.2021.100408 / PMID 34755128", "Espeland D, de Weerd L, Mercer JB (2022). Health effects of voluntary exposure to cold water – a continuing subject of debate. Int J Circumpolar Health, 81(1), 2111789. doi:10.1080/22423982.2022.2111789 / PMID 36137565", "Tipton MJ, Collier N, Massey H, Corbett J, Harper M (2017). Cold water immersion: kill or cure? Exp Physiol, 102(11), 1335–1355. doi:10.1113/EP086283 / PMID 28833689", "Buijze GA, Sierevelt IN, van der Heijden BC, Dijkgraaf MG, Frings-Dresen MH (2016). The effect of cold showering on health and work: a randomized controlled trial. PLoS One, 11(9), e0161749. doi:10.1371/journal.pone.0161749 / PMID 27631616", "Roberts LA, Raastad T, Markworth JF, Figueiredo VC o.fl. (2015). Post-exercise cold water immersion attenuates acute anabolic signalling and long-term adaptations in muscle to strength training. J Physiol, 593(18), 4285–4301. doi:10.1113/JP270570 / PMID 26174323"]}]'::jsonb, 13, 'exercise', false, 24, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('naering-protein-i-hverri-maltid', 'Prótein í hverri máltíð', 'Hvers vegna prótein skiptir máli, hversu mikið við þurfum og hvernig best er að dreifa því yfir daginn', 'slides', '[{"layout": "stat", "title": "Prótein vinnur fyrir þig", "body": "Líkaminn notar orku til að melta mat, taka hann upp og vinna úr honum. Þetta kallast varmamyndun fæðu. Hún er langmest fyrir prótein: um 20–30% af orkunni í próteini fara í þessa vinnu, en aðeins 5–10% af orku kolvetna og 0–3% af orku fitu.\n\nÞetta er ein af nokkrum ástæðum þess að prótein er góður grunnur í hverri máltíð.", "stat": "20–30%", "caption": "af orku próteins fer í að melta það og vinna úr því", "refs": ["Westerterp, Nutr Metab 2004"]}, {"layout": "text", "title": "Hvað er prótein?", "body": "Prótein eru byggð úr amínósýrum. Níu þeirra eru lífsnauðsynlegar, það er að segja líkaminn getur ekki búið þær til og þarf að fá þær úr fæðunni.\n\nÚr próteinum byggir líkaminn vöðva, bandvef, ensím, hormón og mótefni. Hann á engan sérstakan próteinforða á borð við fituforðann. Ef of lítið prótein fæst til lengri tíma sækir hann það meðal annars í vöðvana. Þess vegna skiptir máli að fá prótein reglulega."}, {"layout": "text", "title": "Hvað eru gæðaprótein?", "body": "Egg, fiskur, kjöt og mjólkurvörur eins og skyr innihalda allar lífsnauðsynlegu amínósýrurnar í góðum hlutföllum og nýtast vel.\n\nJurtaprótein úr baunum, linsum, soja, hnetum og heilkorni geta líka dugað vel, sérstaklega þegar ólíkum uppsprettum er blandað saman yfir daginn. Embætti landlæknis hvetur til þess að velja fisk, baunir og linsur oftar en rautt kjöt og að takmarka unnar kjötvörur.", "refs": ["Embætti landlæknis 2025"]}, {"layout": "bullets", "title": "Þrjár leiðir sem prótein hjálpar", "body": "Prótein gerir meira en að byggja vöðva.", "items": ["Varmamyndun: meiri orka fer í að vinna úr próteini en úr kolvetnum eða fitu.", "Mettun: próteinríkar máltíðir auka seddutilfinningu og losun mettunarhormóna.", "Vöðvar: nægt prótein styður við viðhald vöðvamassa, ekki síst við þyngdartap og með hækkandi aldri.", "Með styrktarþjálfun styður prótein við aukinn vöðvamassa og styrk."], "refs": ["Westerterp, Nutr Metab 2004", "Leidy o.fl., Am J Clin Nutr 2015", "Morton o.fl., Br J Sports Med 2018"]}, {"layout": "text", "title": "Mettun: raunveruleg en hófleg áhrif", "body": "Í yfirlitsgrein Leidy og félaga kom fram að máltíðir með meira próteini auka seddutilfinningu og mettunarhormón. Í stýrðum rannsóknum þar sem fólk borðaði færri hitaeiningar fylgdi meira prótein aðeins meira fitutap og betri varðveisla vöðvamassa.\n\nRannsóknir sýna hins vegar ekki alltaf að fólk borði minna í næstu máltíð. Prótein er því gagnlegt verkfæri, ekki töfralausn.", "refs": ["Leidy o.fl., Am J Clin Nutr 2015"]}, {"layout": "text", "title": "Vöðvarnir eru alltaf í endurnýjun", "body": "Vöðvaprótein eru stöðugt að brotna niður og byggjast upp. Eftir próteinríka máltíð eykst nýmyndun vöðvapróteina í nokkrar klukkustundir. Amínósýran leucín, sem er ríkuleg í mjólkurvörum, eggjum, fiski og kjöti, gefur þar mikilvægt merki.\n\nStyrktarþjálfun eykur þessi áhrif. Vöðvar skipta máli fyrir styrk, jafnvægi og efnaskipti og fyrir sjálfstæði á efri árum.", "refs": ["Areta o.fl., J Physiol 2013", "Morton o.fl., Br J Sports Med 2018"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Nokkrar lykilrannsóknir um magn og dreifingu próteins:", "items": ["Safngreining á 49 slembirannsóknum (1.863 þátttakendur): viðbótarprótein með styrktarþjálfun jók vöðvamassa og styrk lítillega.", "Ávinningurinn fyrir vöðvamassa jókst ekki umfram heildarneyslu upp á um 1,6 g/kg á dag.", "Jöfn dreifing, um 30 g í hverri máltíð, gaf 25% meiri nýmyndun vöðvapróteina en skökk dreifing (lítil rannsókn, 8 manns).", "Eftir æfingu gáfu 20 g á þriggja klukkustunda fresti betri svörun en smærri eða stærri skammtar sjaldnar."], "refs": ["Morton o.fl., Br J Sports Med 2018", "Mamerow o.fl., J Nutr 2014", "Areta o.fl., J Physiol 2013"]}, {"layout": "bullets", "title": "Hversu mikið prótein?", "body": "Þörfin fer eftir aldri, hreyfingu og heilsu. Gróf viðmið á hvert kíló líkamsþyngdar:", "items": ["Fullorðnir almennt: ráðlögð neysla er 0,83 g/kg á dag, eða 10–20% af orkunni (NNR 2023).", "65 ára og eldri: 1,2–1,5 g/kg á dag samkvæmt NNR 2023; PROT-AGE mælir með minnst 1,0–1,2 g/kg.", "Fólk í reglulegri styrktarþjálfun: um 1,2–1,6 g/kg á dag; umfram 1,6 g/kg sást ekki frekari ávinningur fyrir vöðva.", "Dæmi: 80 kg manneskja þarf um 66 g á dag að lágmarki, en virk manneskja gæti miðað við 100–130 g.", "Ef þú ert með nýrnasjúkdóm skaltu ræða próteinmagn við lækni áður en þú eykur það."], "refs": ["NNR 2023", "Bauer o.fl., JAMDA 2013", "Morton o.fl., Br J Sports Med 2018"]}, {"layout": "stat", "title": "Dreifðu próteininu yfir daginn", "body": "Margir borða lítið prótein í morgunmat og hádegismat en mikið á kvöldin. Rannsóknir benda til að vöðvarnir nýti prótein betur þegar því er dreift jafnar.\n\nSchoenfeld og Aragon leggja til um 0,4 g/kg í hverri máltíð, í að minnsta kosti fjórum máltíðum, fyrir þá sem vilja hámarka vöðvauppbyggingu. Fyrir 70 kg manneskju eru það um 28 g.", "stat": "25–30 g", "caption": "prótein í hverri aðalmáltíð er hagnýtt markmið fyrir marga", "refs": ["Schoenfeld & Aragon, JISSN 2018", "Mamerow o.fl., J Nutr 2014"]}, {"layout": "bullets", "title": "Íslenskar próteinuppsprettur", "body": "Gróf viðmið um próteinmagn í algengum skömmtum:", "items": ["Hreint skyr, 200 g: um 20 g prótein.", "Fiskur, t.d. þorskur, ýsa eða lax, 150 g eldaður: um 30 g.", "Lambakjöt eða kjúklingur, 100 g eldað: um 25 g.", "Tvö egg: um 12 g.", "Mjólkurglas, 250 ml: um 8 g.", "Soðnar baunir eða linsur, 120 g: um 10 g, auk trefja."]}, {"layout": "tip", "title": "Ráð: byrjaðu á morgunmatnum", "body": "Í morgunmatinn vantar oftast mest prótein. Einföld skipti geta skipt máli:\n\nHreint skyr með höfrum og berjum, egg á grófu brauði eða hafragrautur soðinn í mjólk með skeið af skyri.\n\nPrófaðu að byggja diskinn í kringum próteinið: veldu fyrst próteingjafann og bættu svo við grænmeti og heilkorni."}, {"layout": "bullets", "title": "Dæmi um dag", "body": "Svona gæti venjulegur dagur litið út með um 25–30 g af próteini í hverri máltíð:", "items": ["Morgunmatur: skyr með höfrum, berjum og smá hnetum.", "Hádegismatur: gróft brauð með eggjum eða reyktum laxi og stórt salat.", "Kvöldmatur: ofnbakaður fiskur með kartöflum og miklu grænmeti.", "Millimál ef þarf: mjólkurglas, hnetur eða harðsoðið egg."]}, {"layout": "text", "title": "Matur fyrst", "body": "Flestir geta fengið nóg prótein úr venjulegum mat. Próteinduft er ekki nauðsynlegt og ekki betra en matur; það getur þó verið þægilegt fyrir suma.\n\nMatur gefur líka önnur næringarefni: fiskur gefur D-vítamín og ómega-3-fitusýrur, mjólkurvörur kalk og baunir trefjar. Landlæknir mælir með fiski tvisvar til þrisvar í viku og að rautt kjöt fari ekki yfir 350 g á viku.", "refs": ["Embætti landlæknis 2025"]}, {"layout": "sources", "title": "Heimildir", "body": "Rannsóknir og ráðleggingar sem vísað er í í þessari fræðslu.", "items": ["Westerterp KR (2004). Diet induced thermogenesis. Nutrition & Metabolism (Lond), 1(1), 5. doi:10.1186/1743-7075-1-5 / PMID 15507147", "Leidy HJ, Clifton PM, Astrup A, Wycherley TP, Westerterp-Plantenga MS, Luscombe-Marsh ND, o.fl. (2015). The role of protein in weight loss and maintenance. American Journal of Clinical Nutrition, 101(6), 1320S–1329S. doi:10.3945/ajcn.114.084038 / PMID 25926512", "Morton RW, Murphy KT, McKellar SR, Schoenfeld BJ, Henselmans M, Helms E, o.fl. (2018). A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults. British Journal of Sports Medicine, 52(6), 376–384. doi:10.1136/bjsports-2017-097608 / PMID 28698222", "Mamerow MM, Mettler JA, English KL, Casperson SL, Arentson-Lantz E, Sheffield-Moore M, o.fl. (2014). Dietary protein distribution positively influences 24-h muscle protein synthesis in healthy adults. Journal of Nutrition, 144(6), 876–880. doi:10.3945/jn.113.185280 / PMID 24477298", "Areta JL, Burke LM, Ross ML, Camera DM, West DW, Broad EM, o.fl. (2013). Timing and distribution of protein ingestion during prolonged recovery from resistance exercise alters myofibrillar protein synthesis. Journal of Physiology, 591(9), 2319–2331. doi:10.1113/jphysiol.2012.244897 / PMID 23459753", "Schoenfeld BJ, Aragon AA (2018). How much protein can the body use in a single meal for muscle-building? Implications for daily protein distribution. Journal of the International Society of Sports Nutrition, 15, 10. doi:10.1186/s12970-018-0215-1 / PMID 29497353", "Bauer J, Biolo G, Cederholm T, Cesari M, Cruz-Jentoft AJ, Morley JE, o.fl. (2013). Evidence-based recommendations for optimal dietary protein intake in older people: a position paper from the PROT-AGE Study Group. Journal of the American Medical Directors Association, 14(8), 542–559. doi:10.1016/j.jamda.2013.05.021 / PMID 23867520", "Blomhoff R, Andersen R, Arnesen EK, Christensen JJ, Eneroth H, Erkkola M, o.fl. (2023). Nordic Nutrition Recommendations 2023. Kaupmannahöfn: Norræna ráðherranefndin. doi:10.6027/nord2023-003", "Embætti landlæknis (2025). Ráðleggingar um mataræði (endurskoðaðar 12. mars 2025). Reykjavík: Embætti landlæknis. https://island.is/mataraedi-radleggingar-landlaeknis"]}]'::jsonb, 15, 'nutrition', false, 31, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('naering-gjorunnin-matvaeli', 'Gjörunnin matvæli', 'Hvað þau eru, hvers vegna við borðum meira af þeim og hvernig má skipta þeim út', 'slides', '[{"layout": "stat", "title": "Sama fólk, annað fæði", "body": "Í stýrðri rannsókn bjuggu 20 fullorðnir á rannsóknarstöð í fjórar vikur. Í tvær vikur fengu þeir gjörunnið fæði og í tvær vikur óunnið, og máttu borða eins mikið og þeir vildu.\n\nÁ gjörunna fæðinu borðuðu þeir að meðaltali um 500 hitaeiningum meira á dag.", "stat": "~500 kkal", "caption": "meira borðað á dag af gjörunnu fæði en óunnu", "refs": ["Hall o.fl., Cell Metab 2019"]}, {"layout": "text", "title": "Vinnsla er ekki vandamálið í sjálfu sér", "body": "Nær allur matur er unninn á einhvern hátt. Frysting, gerilsneyðing, skyrgerð, reyking og niðursuða eru allt vinnsluaðferðir, og margar þeirra gera mat öruggari og aðgengilegri.\n\nGjörunnin matvæli eru annað. Þau eru iðnaðarframleiddar blöndur, oft að mestu gerðar úr efnum sem unnin eru úr matvælum og aukefnum, með litlu eða engu af heilum mat.", "refs": ["Monteiro o.fl., Public Health Nutr 2019"]}, {"layout": "bullets", "title": "NOVA-flokkunin: fjórir flokkar", "body": "NOVA-kerfið flokkar matvæli eftir því hversu mikið og hvernig þau eru unnin:", "items": ["1. Óunnin eða lítið unnin: fiskur, egg, mjólk, kjöt, grænmeti, ávextir, hafrar, baunir, frosið grænmeti.", "2. Matreiðsluhráefni: smjör, olía, salt, sykur, notuð í hófi við matargerð.", "3. Unnin matvæli: ostur, einfalt brauð, niðursoðnar baunir, reyktur eða saltaður fiskur.", "4. Gjörunnin: gosdrykkir, sælgæti, snakk, pakkakex, sykrað morgunkorn, pylsur, naggar, skyndinúðlur."], "refs": ["Monteiro o.fl., Public Health Nutr 2019"]}, {"layout": "bullets", "title": "Hvernig þekki ég gjörunnin matvæli?", "body": "Innihaldslýsingin segir mest. Merki um gjörunna vöru:", "items": ["Löng innihaldslýsing með efnum sem þú myndir ekki nota í eigin eldhúsi.", "Til dæmis glúkósasíróp, maltódextrín, hert fita, einangrað prótein, bragðefni, bindiefni, litarefni eða sætuefni.", "Tilbúin til neyslu beint úr pakkanum, með langt geymsluþol.", "Oft mikið markaðssett og hönnuð til að vera sérstaklega bragðgóð."], "refs": ["Monteiro o.fl., Public Health Nutr 2019"]}, {"layout": "text", "title": "Rannsókn Halls nánar", "body": "Máltíðirnar voru samræmdar með tilliti til hitaeininga, orkuþéttni, sykurs, salts, trefja og orkuefna. Samt borðaði fólk um 508 hitaeiningum meira á dag á gjörunna fæðinu, einkum úr kolvetnum og fitu en ekki úr próteini.\n\nÞátttakendur þyngdust um 0,9 kg á tveimur vikum á gjörunna fæðinu en léttust um 0,9 kg á óunna fæðinu. Rannsóknin var lítil og stutt, en hún sýnir orsakaáhrif á orkuneyslu en ekki aðeins tengsl.", "refs": ["Hall o.fl., Cell Metab 2019"]}, {"layout": "text", "title": "Af hverju borðum við meira?", "body": "Ástæðurnar eru ekki fullþekktar, en rannsakendur hafa nokkrar tilgátur. Í rannsókn Halls borðaði fólk gjörunnu máltíðirnar hraðar. Mjúkur matur sem þarf lítið að tyggja getur farið niður áður en mettunarmerki líkamans ná að berast.\n\nMikil orkuþéttni og samspil fitu, sykurs og salts gætu líka átt þátt. Hvað sem skýringunni líður er niðurstaðan sú sama: auðveldara er að borða of mikið af gjörunnum mat.", "refs": ["Hall o.fl., Cell Metab 2019"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Heildarmyndin úr stærstu samantektunum:", "items": ["Regnhlífarsamantekt (45 safngreiningar, tæplega 10 milljónir þátttakenda): meiri neysla tengdist verri útkomu í 32 af 45 heilsuþáttum.", "Sterkustu tengslin voru við dauðsföll af völdum hjarta- og æðasjúkdóma, sykursýki 2 og kvíða.", "Gæði gagnanna voru þó oft metin lág, enda eru þetta að mestu athugunarrannsóknir sem sýna tengsl, ekki orsakasamband.", "NNR 2023 viðurkennir tengslin en setur ekki sérstaka ráðleggingu um gjörunnin matvæli; aðrar ráðleggingar ná yfir flest þeirra."], "refs": ["Lane o.fl., BMJ 2024", "NNR 2023"]}, {"layout": "text", "title": "Ekki allt gjörunnið er jafn slæmt", "body": "Flokkunin segir til um vinnslu, ekki næringargildi. Norrænu ráðleggingarnar benda á að sumar gjörunnar vörur geti verið ágætar frá næringarsjónarmiði, til dæmis sumt verksmiðjubakað heilkornabrauð eða vítamínbættar vörur.\n\nÞað sem helst ætti að minnka er það sem Embætti landlæknis nefnir: sælgæti, snakk, kökur, kex, sætir drykkir og unnar kjötvörur. Horfðu á heildarmyndina frekar en einstakar vörur.", "refs": ["NNR 2023", "Embætti landlæknis 2025"]}, {"layout": "bullets", "title": "Hagnýt skipti", "body": "Lítil skipti sem safnast saman:", "items": ["Gos eða orkudrykkir → vatn, sódavatn með sítrónu eða ósykrað te.", "Sykrað morgunkorn → hafragrautur eða ósykrað múslí með berjum.", "Pylsur og unnið álegg → egg, fiskur eða afgangar af heimaelduðum kjúklingi.", "Snakk → hnetur, heimapoppað popp eða grænmeti með hummus.", "Bragðbætt skyr → hreint skyr með berjum og smá hunangi ef þú vilt.", "Tilbúnir réttir → einfaldir heimaréttir, eldaðir í stærri skömmtum og frystir."]}, {"layout": "tip", "title": "Ráð: breyttu umhverfinu, ekki viljastyrknum", "body": "Það sem er til heima er það sem við borðum. Kauptu síður heim það sem þú átt erfitt með að stilla þig um, og hafðu auðvelda kosti tilbúna: niðurskorið grænmeti, soðin egg, skyr og ávexti.\n\nMarkmiðið er ekki fullkomnun. Ef meginhluti fæðunnar er lítið unninn er pláss fyrir annað öðru hverju."}, {"layout": "bullets", "title": "Innkaupalisti sem einfaldar lífið", "body": "Lítið unnin matvæli þurfa ekki að vera dýr eða tímafrek:", "items": ["Frosið grænmeti og frosin ber; þau eru lítið unnin og geymast vel.", "Niðursoðnar baunir, linsur og tómatar.", "Hafrar, bygg og gróft brauð með stuttri innihaldslýsingu.", "Hreint skyr, mjólk og egg.", "Frosinn fiskur, t.d. þorskur, ýsa eða lax.", "Kartöflur, rótargrænmeti og árstíðabundnir ávextir."]}, {"layout": "text", "title": "Borðaðu hægar og með athygli", "body": "Þar sem hraði átsins gæti skipt máli er gott að hægja á. Sestu niður við borð, leggðu frá þér símann og tyggðu matinn vel.\n\nMatur sem þarf að tyggja, eins og fiskur, grænmeti, heilkorn og ávextir, hægir sjálfkrafa á okkur og gefur líkamanum tíma til að finna að hann er saddur.", "refs": ["Hall o.fl., Cell Metab 2019"]}, {"layout": "sources", "title": "Heimildir", "body": "Rannsóknir og ráðleggingar sem vísað er í í þessari fræðslu.", "items": ["Hall KD, Ayuketah A, Brychta R, Cai H, Cassimatis T, Chen KY, o.fl. (2019). Ultra-processed diets cause excess calorie intake and weight gain: an inpatient randomized controlled trial of ad libitum food intake. Cell Metabolism, 30(1), 67–77.e3. doi:10.1016/j.cmet.2019.05.008 / PMID 31105044", "Monteiro CA, Cannon G, Levy RB, Moubarac JC, Louzada ML, Rauber F, o.fl. (2019). Ultra-processed foods: what they are and how to identify them. Public Health Nutrition, 22(5), 936–941. doi:10.1017/S1368980018003762 / PMID 30744710", "Lane MM, Gamage E, Du S, Ashtree DN, McGuinness AJ, Gauci S, o.fl. (2024). Ultra-processed food exposure and adverse health outcomes: umbrella review of epidemiological meta-analyses. BMJ, 384, e077310. doi:10.1136/bmj-2023-077310 / PMID 38418082", "Blomhoff R, Andersen R, Arnesen EK, Christensen JJ, Eneroth H, Erkkola M, o.fl. (2023). Nordic Nutrition Recommendations 2023. Kaupmannahöfn: Norræna ráðherranefndin. doi:10.6027/nord2023-003", "Embætti landlæknis (2025). Ráðleggingar um mataræði (endurskoðaðar 12. mars 2025). Reykjavík: Embætti landlæknis. https://island.is/mataraedi-radleggingar-landlaeknis"]}]'::jsonb, 14, 'nutrition', false, 32, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('naering-sykur-insulin-kvidfita', 'Sykur, insúlín og innri kviðfita', 'Hvað gerist í líkamanum, hvað segja rannsóknir um sykraða drykki og hvað skiptir mestu', 'slides', '[{"layout": "stat", "title": "Einn lítri af gosi á dag", "body": "Í danskri slembirannsókn drukku 47 einstaklingar í yfirþyngd einn lítra á dag í sex mánuði af sykruðu gosi, léttmjólk, sykurlausu gosi eða vatni.\n\nHeildarfitumassi breyttist ekki marktækt milli hópa, en í gosshópnum jókst fita í lifur, vöðvum og innri kviðfitu meira en í hinum hópunum.", "stat": "+24–31%", "caption": "meiri aukning í innri kviðfitu í gosshópnum en í hinum hópunum", "refs": ["Maersk o.fl., Am J Clin Nutr 2012"]}, {"layout": "text", "title": "Tvenns konar kviðfita", "body": "Undirhúðarfita liggur rétt undir húðinni. Innri kviðfita liggur dýpra, umhverfis líffærin í kviðarholinu. Fita getur líka safnast í lifur og aðra vefi þar sem hún á ekki heima.\n\nInnri kviðfita og fita í lifur eru virkari í efnaskiptum. Þær tengjast insúlínviðnámi, sykursýki 2 og hjarta- og æðasjúkdómum, jafnvel hjá fólki í kjörþyngd. Því segir vigtin ekki alla söguna.", "refs": ["Neeland o.fl., Lancet Diabetes Endocrinol 2019"]}, {"layout": "text", "title": "Hvað gerir insúlín?", "body": "Insúlín er hormón frá brisinu. Eftir máltíð hækkar blóðsykur og insúlín hjálpar sykrinum inn í vöðva, lifur og fituvef. Á sama tíma dregur insúlín úr losun fitu úr fituvefnum, því að nóg orka er í umferð.\n\nMilli máltíða og á nóttunni lækkar insúlínið og líkaminn sækir meira í fituforðann. Þetta er eðlilegt og lífsnauðsynlegt kerfi sem jafnar út orkuflæðið yfir sólarhringinn."}, {"layout": "text", "title": "Fitnar maður af insúlíni?", "body": "Algengt er að heyra að insúlín „geri mann feitan“. Það er of mikil einföldun. Insúlín stýrir því hvenær orka er geymd og hvenær hún er losuð, en hvort fituforðinn stækkar til lengri tíma ræðst fyrst og fremst af orkujafnvægi.\n\nÍ stýrðum rannsóknum tapaðist ekki meiri fita þegar kolvetni, og þar með insúlín, voru minnkuð en þegar fita var minnkuð með sama hitaeiningafjölda.", "refs": ["Hall & Guo, Gastroenterology 2017", "Hall o.fl., Cell Metab 2015"]}, {"layout": "text", "title": "Hvað sýndu tilraunirnar?", "body": "Í fyrri rannsókn Halls og félaga fengu 19 einstaklingar annaðhvort minni fitu eða minni kolvetni, með sömu hitaeiningum. Fitutapið var meira þegar fitan var minnkuð.\n\nÍ þeirri síðari borðaði fólk um 550–700 hitaeiningum minna á dag af lítið unnu, kolvetnaríku jurtafæði en af ketófæði, þótt insúlín væri hærra á kolvetnaríka fæðinu. Gæði fæðunnar og hversu mikið við borðum skipta meira máli en insúlínið eitt og sér.", "refs": ["Hall o.fl., Cell Metab 2015", "Hall o.fl., Nat Med 2021"]}, {"layout": "text", "title": "Insúlínviðnám: þegar kerfið þreytist", "body": "Við insúlínviðnám svara frumur líkamans insúlíni verr. Brisið bætir það upp með því að framleiða meira insúlín. Ef það nær ekki lengur að halda í við getur blóðsykur hækkað smám saman.\n\nÝmislegt tengist insúlínviðnámi, meðal annars umframfita, sérstaklega innri kviðfita og fita í lifur, hreyfingarleysi, erfðir og aldur. Góðu fréttirnar eru þær að lífsvenjur geta haft mikil áhrif.", "refs": ["Kahn o.fl., Nature 2006", "Neeland o.fl., Lancet Diabetes Endocrinol 2019"]}, {"layout": "text", "title": "Af hverju sykraðir drykkir?", "body": "Hitaeiningar í fljótandi formi metta illa og auðvelt er að drekka mikið af þeim án þess að borða minna á móti.\n\nVenjulegur sykur er að hálfu frúktósi (ávaxtasykur) sem er einkum unninn í lifrinni. Þegar mikið berst í einu getur lifrin breytt hluta hans í fitu. Í tilraun þar sem fólk fékk fjórðung orkunnar úr sætum drykkjum í tíu vikur jókst innri kviðfita aðeins í frúktósahópnum, þó að þyngdaraukning væri svipuð í báðum hópum.", "refs": ["Stanhope o.fl., J Clin Invest 2009"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Helstu niðurstöður um sykur og sykraða drykki:", "items": ["Minni sykur: 0,8 kg léttara að meðaltali. Engin breyting varð þegar sykri var skipt út fyrir önnur kolvetni með sömu orku.", "Sykur virðist því hafa áhrif á þyngd að mestu í gegnum aukna orkuneyslu.", "Einn til tveir sykraðir drykkir á dag tengdust 26% meiri áhættu á sykursýki 2 en minna en einn á mánuði.", "Hver daglegur sykraður drykkur tengdist 13% meiri áhættu á sykursýki 2, einnig eftir leiðréttingu fyrir líkamsfitu.", "Sykrað gos í hálft ár jók fitu í lifur og innri kviðfitu meira en mjólk, sykurlaust gos eða vatn."], "refs": ["Te Morenga o.fl., BMJ 2013", "Malik o.fl., Diabetes Care 2010", "Imamura o.fl., BMJ 2015", "Maersk o.fl., Am J Clin Nutr 2012"]}, {"layout": "stat", "title": "Hversu mikill sykur?", "body": "Norrænu ráðleggingarnar og WHO mæla með að viðbættur og frjáls sykur sé undir 10% af orkunni, og helst minna. Fyrir 2.000 hitaeininga dag eru það innan við 50 g, eða um 12 teskeiðar.\n\nTil samanburðar getur ein hálfs lítra flaska af sykruðu gosi innihaldið um 50 g af sykri.", "stat": "< 10%", "caption": "af orku úr viðbættum og frjálsum sykri – og helst minna", "refs": ["NNR 2023", "WHO 2015"]}, {"layout": "text", "title": "Heilir ávextir eru ekki vandamálið", "body": "Frjáls sykur er viðbættur sykur ásamt sykri í safa, hunangi og sírópi. Sykur inni í heilum ávöxtum og grænmeti telst ekki með, því að hann kemur í pakka með trefjum, vatni og næringarefnum.\n\nRannsóknir tengja meiri neyslu ávaxta og grænmetis við minni áhættu á hjarta- og æðasjúkdómum og ótímabærum dauða. Landlæknir mælir með að minnsta kosti fimm skömmtum á dag (um 500 g), þar af minnst helmingi grænmeti.", "refs": ["WHO 2015", "Aune o.fl., Int J Epidemiol 2017", "Embætti landlæknis 2025"]}, {"layout": "bullets", "title": "Hvað tengist minni innri kviðfitu?", "body": "Rannsóknir benda til að eftirfarandi geti hjálpað:", "items": ["Regluleg hreyfing, sem getur minnkað innri kviðfitu jafnvel þótt vigtin hreyfist lítið.", "Hófleg minnkun hitaeininga ef umframþyngd er til staðar.", "Færri sykraðir drykkir.", "Trefjarík, lítið unnin fæða með grænmeti, ávöxtum, heilkorni og próteini.", "Minni áfengisneysla og nægur svefn eru líka hluti af heildarmyndinni."], "refs": ["Verheggen o.fl., Obes Rev 2016", "Maersk o.fl., Am J Clin Nutr 2012", "Neeland o.fl., Lancet Diabetes Endocrinol 2019"]}, {"layout": "bullets", "title": "Hagnýt skref", "body": "Byrjaðu á því sem skilar mestu:", "items": ["Skiptu sykruðum drykkjum út fyrir vatn, sódavatn, ósykrað kaffi eða te.", "Borðaðu ávöxtinn í stað þess að drekka safann.", "Veldu hreint skyr eða jógúrt og sættu með berjum.", "Skoðaðu „þar af sykurtegundir“ á umbúðum.", "Gerðu sætindi að meðvituðum eftirrétti frekar en daglegum vana.", "Fylltu hálfan diskinn af grænmeti."], "refs": ["Embætti landlæknis 2025"]}, {"layout": "tip", "title": "Ráð: skiptu út frekar en að banna", "body": "Það er auðveldara að skipta einhverju út en að hætta alveg. Sykurlaust gos getur verið gagnleg brú frá sykruðu gosi, en vatn er besti kosturinn til lengri tíma.\n\nPrófaðu í tvær vikur að drekka aðeins vatn, sódavatn, kaffi, te eða mjólk með mat. Margir finna að löngunin í sætt minnkar þegar bragðlaukarnir venjast minni sykri.", "refs": ["Maersk o.fl., Am J Clin Nutr 2012", "Embætti landlæknis 2025"]}, {"layout": "sources", "title": "Heimildir", "body": "Rannsóknir og ráðleggingar sem vísað er í í þessari fræðslu.", "items": ["Maersk M, Belza A, Stødkilde-Jørgensen H, Ringgaard S, Chabanova E, Thomsen H, o.fl. (2012). Sucrose-sweetened beverages increase fat storage in the liver, muscle, and visceral fat depot: a 6-mo randomized intervention study. American Journal of Clinical Nutrition, 95(2), 283–289. doi:10.3945/ajcn.111.022533 / PMID 22205311", "Neeland IJ, Ross R, Després JP, Matsuzawa Y, Yamashita S, Shai I, o.fl. (2019). Visceral and ectopic fat, atherosclerosis, and cardiometabolic disease: a position statement. Lancet Diabetes & Endocrinology, 7(9), 715–725. doi:10.1016/S2213-8587(19)30084-1 / PMID 31301983", "Hall KD, Guo J (2017). Obesity energetics: body weight regulation and the effects of diet composition. Gastroenterology, 152(7), 1718–1727.e3. doi:10.1053/j.gastro.2017.01.052 / PMID 28193517", "Hall KD, Bemis T, Brychta R, Chen KY, Courville A, Crayner EJ, o.fl. (2015). Calorie for calorie, dietary fat restriction results in more body fat loss than carbohydrate restriction in people with obesity. Cell Metabolism, 22(3), 427–436. doi:10.1016/j.cmet.2015.07.021 / PMID 26278052", "Hall KD, Guo J, Courville AB, Boring J, Brychta R, Chen KY, o.fl. (2021). Effect of a plant-based, low-fat diet versus an animal-based, ketogenic diet on ad libitum energy intake. Nature Medicine, 27(2), 344–353. doi:10.1038/s41591-020-01209-1 / PMID 33479499", "Kahn SE, Hull RL, Utzschneider KM (2006). Mechanisms linking obesity to insulin resistance and type 2 diabetes. Nature, 444(7121), 840–846. doi:10.1038/nature05482 / PMID 17167471", "Stanhope KL, Schwarz JM, Keim NL, Griffen SC, Bremer AA, Graham JL, o.fl. (2009). Consuming fructose-sweetened, not glucose-sweetened, beverages increases visceral adiposity and lipids and decreases insulin sensitivity in overweight/obese humans. Journal of Clinical Investigation, 119(5), 1322–1334. doi:10.1172/JCI37385 / PMID 19381015", "Te Morenga L, Mallard S, Mann J (2013). Dietary sugars and body weight: systematic review and meta-analyses of randomised controlled trials and cohort studies. BMJ, 346, e7492. doi:10.1136/bmj.e7492 / PMID 23321486", "Malik VS, Popkin BM, Bray GA, Després JP, Willett WC, Hu FB (2010). Sugar-sweetened beverages and risk of metabolic syndrome and type 2 diabetes: a meta-analysis. Diabetes Care, 33(11), 2477–2483. doi:10.2337/dc10-1079 / PMID 20693348", "Imamura F, O''Connor L, Ye Z, Mursu J, Hayashino Y, Bhupathiraju SN, o.fl. (2015). Consumption of sugar sweetened beverages, artificially sweetened beverages, and fruit juice and incidence of type 2 diabetes: systematic review, meta-analysis, and estimation of population attributable fraction. BMJ, 351, h3576. doi:10.1136/bmj.h3576 / PMID 26199070", "Blomhoff R, Andersen R, Arnesen EK, Christensen JJ, Eneroth H, Erkkola M, o.fl. (2023). Nordic Nutrition Recommendations 2023. Kaupmannahöfn: Norræna ráðherranefndin. doi:10.6027/nord2023-003", "World Health Organization (2015). Guideline: sugars intake for adults and children. Genf: WHO. ISBN 978-92-4-154902-8 / PMID 25905159", "Aune D, Giovannucci E, Boffetta P, Fadnes LT, Keum N, Norat T, o.fl. (2017). Fruit and vegetable intake and the risk of cardiovascular disease, total cancer and all-cause mortality – a systematic review and dose-response meta-analysis of prospective studies. International Journal of Epidemiology, 46(3), 1029–1056. doi:10.1093/ije/dyw319 / PMID 28338764", "Verheggen RJ, Maessen MF, Green DJ, Hermus AR, Hopman MT, Thijssen DH (2016). A systematic review and meta-analysis on the effects of exercise training versus hypocaloric diet: distinct effects on body weight and visceral adipose tissue. Obesity Reviews, 17(8), 664–690. doi:10.1111/obr.12406 / PMID 27213481", "Embætti landlæknis (2025). Ráðleggingar um mataræði (endurskoðaðar 12. mars 2025). Reykjavík: Embætti landlæknis. https://island.is/mataraedi-radleggingar-landlaeknis"]}]'::jsonb, 15, 'nutrition', false, 33, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('naering-trefjar-heilkorn-timasetning', 'Trefjar, heilkorn og hvenær við borðum', 'Munurinn á heilkorni og fínunnu korni, hvað trefjar gera fyrir okkur og hvað rannsóknir segja um tímasetningu máltíða', 'slides', '[{"layout": "stat", "title": "Trefjar skipta máli", "body": "Í stórri samantekt á 185 ferilrannsóknum og 58 klínískum rannsóknum var borin saman heilsa þeirra sem borðuðu mest af trefjum og þeirra sem borðuðu minnst.\n\nMest trefjaneysla tengdist 15–30% minni dánartíðni og minni áhættu á kransæðasjúkdómi, heilablóðfalli, sykursýki 2 og ristilkrabbameini.", "stat": "15–30%", "caption": "minni áhætta hjá þeim sem borða mest af trefjum", "refs": ["Reynolds o.fl., Lancet 2019"]}, {"layout": "text", "title": "Heilkorn eða fínunnið korn?", "body": "Kornið hefur þrjá hluta: hýði (klíð), kím og fræhvítu. Í heilkorni eru allir hlutarnir með, og þar með trefjar, vítamín, steinefni og holl fita.\n\nÍ fínunnu korni, eins og hvítu hveiti, hvítu brauði, hvítum hrísgrjónum og flestu kexi og kökum, hafa hýðið og kímið verið fjarlægð. Eftir situr aðallega sterkja, með mun minna af trefjum og næringarefnum.", "refs": ["Embætti landlæknis 2025"]}, {"layout": "quote", "title": "Á að minnka korn?", "body": "Oft heyrist að gott sé að „skera niður“ korn eða kolvetni. Rannsóknirnar gera þó skýran greinarmun: það er fínunna kornið og sykurinn sem gott er að minnka. Heilkorn tengist hins vegar betri heilsu og er ráðlagt bæði í norrænu ráðleggingunum og hjá Embætti landlæknis.\n\nLykillinn er að skipta út, ekki að sleppa.", "caption": "Reynolds o.fl., Lancet 2019 (lausleg þýðing á niðurstöðu höfunda): Að auka trefjar og skipta fínunnu korni út fyrir heilkorn er líklegt til að gagnast heilsu.", "refs": ["Reynolds o.fl., Lancet 2019", "NNR 2023", "Embætti landlæknis 2025"]}, {"layout": "bullets", "title": "Hvað gera trefjar í líkamanum?", "body": "Trefjar eru sá hluti jurtafæðu sem við meltum ekki sjálf, en þær vinna mikilvæg störf:", "items": ["Auka rúmmál máltíðar og seddutilfinningu án margra hitaeininga.", "Hægja á upptöku sykurs, og blóðsykurinn hækkar því jafnar eftir máltíð.", "Leysanlegar trefjar, t.d. úr höfrum og byggi, geta lækkað kólesteról í blóði.", "Gerlarnir í ristlinum gerja trefjar og mynda meðal annars stuttar fitusýrur sem næra þarmaslímhúðina.", "Stuðla að reglulegum hægðum."], "refs": ["Reynolds o.fl., Lancet 2019"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Niðurstöður stærstu samantekta og ráðlegginga:", "items": ["Klínískar rannsóknir: meiri trefjar tengdust lægri líkamsþyngd, blóðþrýstingi og heildarkólesteróli.", "Mest áhættulækkun sást við 25–29 g af trefjum á dag, og meira gæti gefið enn meiri ávinning.", "Hver 90 g af heilkorni á dag tengdust 19% minni áhættu á kransæðasjúkdómi og 17% minni heildardánartíðni.", "Sykurstuðull fæðu sagði minna um heilsu en trefjar og heilkorn.", "NNR 2023 fann engin skaðleg áhrif af mikilli heilkornaneyslu."], "refs": ["Reynolds o.fl., Lancet 2019", "Aune o.fl., BMJ 2016", "NNR 2023"]}, {"layout": "stat", "title": "Markmiðið: 90 g af heilkorni", "body": "Bæði NNR 2023 og Embætti landlæknis mæla með um 90 g af heilkorni á dag, eða um þremur skömmtum. Trefjamarkmiðið er að minnsta kosti 25 g á dag fyrir konur og 35 g fyrir karla.\n\nGróf dæmi um skammt: hafragrautur úr um 30 g af höfrum, sneið af grófu heilkornabrauði eða skál af byggi eða heilkornapasta.", "stat": "90 g", "caption": "heilkorn á dag, um þrír skammtar", "refs": ["NNR 2023", "Embætti landlæknis 2025"]}, {"layout": "bullets", "title": "Góðir trefjagjafar úr íslenskri búð", "body": "Auðvelt er að auka trefjarnar með hráefni sem flestir þekkja:", "items": ["Hafrar og hafragrautur; bygg og byggflögur, líka íslenskt bygg.", "Rúgbrauð og annað gróft brauð; sumt rúgbrauð er sætt, svo að gott er að skoða sykurinn.", "Heilkornapasta og hýðishrísgrjón í stað hvítra.", "Baunir, linsur og kjúklingabaunir.", "Grænmeti, kartöflur með hýði og ber, t.d. bláber og krækiber.", "Hnetur, fræ og hörfræ."]}, {"layout": "bullets", "title": "Lestu á umbúðirnar", "body": "„Gróft“ eða brúnt brauð er ekki alltaf heilkornabrauð. Þetta hjálpar:", "items": ["Heilkornamjöl ætti að vera fremst í innihaldslýsingunni.", "Vara má kallast trefjarík ef hún inniheldur minnst 6 g af trefjum í 100 g.", "Skráargatið auðveldar val á vörum með meiri trefjum og minni sykri, salti og fitu.", "Berðu saman sykurinn í brauði og morgunkorni; munurinn getur verið mikill."]}, {"layout": "tip", "title": "Ráð: auktu trefjarnar smám saman", "body": "Ef þú borðar lítið af trefjum í dag skaltu auka þær hægt, til dæmis á tveimur til þremur vikum, og drekka nóg vatn. Loft í maga er algengt í byrjun og minnkar yfirleitt þegar þarmaflóran aðlagast.\n\nEf þú ert með meltingarsjúkdóm, t.d. iðraólgu, er gott að ræða breytingar við lækni eða næringarfræðing."}, {"layout": "text", "title": "Skiptir máli hvenær við borðum?", "body": "Líkaminn fylgir dægursveiflu sem hefur áhrif á hungur, orkunotkun og efnaskipti. Í lítilli, vel stýrðri víxlrannsókn borðuðu 16 einstaklingar í yfirþyngd sama mat, en í annarri lotunni voru máltíðirnar færðar um fjórar klukkustundir aftar.\n\nSeinni máltíðirnar juku hungur, breyttu hungurhormónum og drógu úr orkunotkun í vöku. Þetta bendir til að seint át geti ýtt undir ofát, en rannsóknin var stutt.", "refs": ["Vujović o.fl., Cell Metab 2022"]}, {"layout": "bullets", "title": "Tímasetning: rannsóknir eru blendnar", "body": "Þegar horft er á lengri rannsóknir verður myndin hófstilltari:", "items": ["Tímastýrt át (16:8) í 12 vikur skilaði ekki meira þyngdartapi en að borða yfir daginn (116 þátttakendur).", "Hitaeiningaskerðing með átta klukkustunda glugga í eitt ár gaf ekki marktækt betri árangur en sama skerðing án glugga (139 þátttakendur).", "NNR 2023: ekki eru nægar sannanir til að setja ráðleggingar um tímasetningu eða fjölda máltíða.", "Hvað og hversu mikið við borðum skiptir því mestu; tímasetning getur hjálpað sumum."], "refs": ["Lowe o.fl., JAMA Intern Med 2020", "Liu o.fl., N Engl J Med 2022", "NNR 2023"]}, {"layout": "bullets", "title": "Hagnýt ráð um tímasetningu", "body": "Veldu það sem hentar þínum degi:", "items": ["Reglulegar máltíðir sem passa við rútínuna þína.", "Ef þú ert svöng eða svangur á kvöldin: skoðaðu hvort morgun- og hádegismatur hafi verið of lítill.", "Settu prótein og trefjar í fyrri máltíðir dagsins.", "Forðastu stöðugt nart fyrir framan skjá seint á kvöldin.", "Mörgum finnst betra að ljúka kvöldmat tveimur til þremur tímum fyrir svefn."], "refs": ["Vujović o.fl., Cell Metab 2022"]}, {"layout": "bullets", "title": "Samantekt", "body": "Það sem gott er að taka með sér:", "items": ["Heilkorn er hollt; það er fínunna kornið og sykurinn sem gott er að minnka.", "Stefndu á um 90 g af heilkorni og 25–35 g af trefjum á dag.", "Auktu trefjarnar smám saman og drekktu vatn með.", "Tímasetning skiptir minna máli en gæði og magn matarins.", "Seint kvöldát getur aukið hungur; reglulegar máltíðir fyrr á deginum henta mörgum."], "refs": ["Reynolds o.fl., Lancet 2019", "NNR 2023", "Embætti landlæknis 2025"]}, {"layout": "sources", "title": "Heimildir", "body": "Rannsóknir og ráðleggingar sem vísað er í í þessari fræðslu.", "items": ["Reynolds A, Mann J, Cummings J, Winter N, Mete E, Te Morenga L (2019). Carbohydrate quality and human health: a series of systematic reviews and meta-analyses. Lancet, 393(10170), 434–445. doi:10.1016/S0140-6736(18)31809-9 / PMID 30638909", "Aune D, Keum N, Giovannucci E, Fadnes LT, Boffetta P, Greenwood DC, o.fl. (2016). Whole grain consumption and risk of cardiovascular disease, cancer, and all cause and cause specific mortality: systematic review and dose-response meta-analysis of prospective studies. BMJ, 353, i2716. doi:10.1136/bmj.i2716 / PMID 27301975", "Blomhoff R, Andersen R, Arnesen EK, Christensen JJ, Eneroth H, Erkkola M, o.fl. (2023). Nordic Nutrition Recommendations 2023. Kaupmannahöfn: Norræna ráðherranefndin. doi:10.6027/nord2023-003", "Embætti landlæknis (2025). Ráðleggingar um mataræði (endurskoðaðar 12. mars 2025). Reykjavík: Embætti landlæknis. https://island.is/mataraedi-radleggingar-landlaeknis", "Vujović N, Piron MJ, Qian J, Chellappa SL, Nedeltcheva A, Barr D, o.fl. (2022). Late isocaloric eating increases hunger, decreases energy expenditure, and modifies metabolic pathways in adults with overweight and obesity. Cell Metabolism, 34(10), 1486–1498.e7. doi:10.1016/j.cmet.2022.09.007 / PMID 36198293", "Lowe DA, Wu N, Rohdin-Bibby L, Moore AH, Kelly N, Liu YE, o.fl. (2020). Effects of time-restricted eating on weight loss and other metabolic parameters in women and men with overweight and obesity: the TREAT randomized clinical trial. JAMA Internal Medicine, 180(11), 1491–1499. doi:10.1001/jamainternmed.2020.4153 / PMID 32986097", "Liu D, Huang Y, Huang C, Yang S, Wei X, Zhang P, o.fl. (2022). Calorie restriction with or without time-restricted eating in weight loss. New England Journal of Medicine, 386(16), 1495–1504. doi:10.1056/NEJMoa2114833 / PMID 35443107"]}]'::jsonb, 15, 'nutrition', false, 34, true)
