insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('andleg-streita-kortisol-kvidfita', 'Streita, kortisól og innri kviðfita', 'Hvað gerist í líkamanum þegar álagið verður langvarandi – og hvað er hægt að gera', 'slides', '[{"layout": "text", "title": "Streita er ekki bara í höfðinu", "body": "Flest þekkjum við hjartsláttinn fyrir mikilvægan fund eða hnútinn í maganum þegar allt er á síðasta snúningi. Streita er eðlilegt viðbragð líkamans og hjálpar okkur að takast á við áskoranir.\n\nÍ þessum fyrirlestri skoðum við hvað gerist þegar streitan verður langvarandi: hvernig hormónið kortisól virkar, hvernig það tengist fitu í kviðarholi og blóðsykri – og hvað rannsóknir segja í raun um streitu og þyngd."}, {"layout": "bullets", "title": "Bráð streita eða langvarandi streita", "body": "Líkaminn er hannaður fyrir stuttar streitulotur sem hjaðna aftur. Vandinn byrjar þegar kerfið fær aldrei að slökkva á sér.", "items": ["Bráð streita: hjartsláttur eykst, orka losnar og athyglin skerpist – í mínútur eða klukkustundir.", "Eftir á fer líkaminn aftur í jafnvægi og hvílist.", "Langvarandi streita: álagið varir vikum eða mánuðum saman án raunverulegrar hvíldar.", "Þá geta sömu varnarviðbrögðin farið að valda sliti á líkamanum.", "McEwen kallaði þetta slit „allóstatískt álag“ (e. allostatic load)."], "refs": ["McEwen, N Engl J Med 1998"]}, {"layout": "text", "title": "HPA-ásinn: viðvörunarkerfi líkamans", "body": "Þegar heilinn metur aðstæður sem ógn sendir undirstúkan boð til heiladingulsins, sem sendir svo boð til nýrnahettanna. Þær losa kortisól út í blóðið. Þessi keðja kallast HPA-ásinn.\n\nKortisól á að slökkva á kerfinu sjálft þegar hættan er liðin hjá (neikvæð afturvirkni). Við langvarandi álag getur þessi stjórnun raskast, þannig að kortisól helst hærra eða dagssveiflan verður flatari en eðlilegt er.", "refs": ["McEwen, N Engl J Med 1998"]}, {"layout": "bullets", "title": "Hvað gerir kortisól?", "body": "Kortisól er lífsnauðsynlegt hormón. Það er ekki „vont“ – það er magnið og tímalengdin sem skipta máli.", "items": ["Hækkar blóðsykur svo vöðvar og heili fái orku strax.", "Dregur tímabundið úr bólgusvörun.", "Fylgir dægursveiflu: hæst að morgni, lægst að kvöldi.", "Getur aukið löngun í orkuríkan mat, sérstaklega sætan og feitan.", "Hefur áhrif á hvar líkaminn geymir fitu."], "refs": ["McEwen, N Engl J Med 1998", "Adam og Epel, Physiol Behav 2007"]}, {"layout": "stat", "title": "Kortisól og kviðfita", "body": "Í þekktri rannsókn Epel og félaga voru konur með hærra hlutfall mittis og mjaðma (meiri fitu um miðjuna) bornar saman við konur með lægra hlutfall. Þær fyrrnefndu seyttu meira kortisóli við streitu. Grannar konur með fitu um miðjuna vöndust ekki streitunni og héldu áfram að seyta meira kortisóli dag eftir dag.\n\nRannsóknin var þversniðsrannsókn og sýnir tengsl, ekki orsök.", "stat": "59", "caption": "heilbrigðar konur fóru í endurtekin streitupróf á fjórum dögum", "refs": ["Epel o.fl., Psychosom Med 2000"]}, {"layout": "text", "title": "Af hverju safnast fitan á kviðinn?", "body": "Innri kviðfita (iðrafita) liggur umhverfis líffærin í kviðarholinu og er efnaskiptalega virkari en fita undir húð. Hún hefur fleiri viðtaka fyrir kortisól en fita annars staðar.\n\nSkýrasta dæmið er Cushing-heilkenni, þar sem líkaminn framleiðir allt of mikið kortisól: fitan safnast þá einmitt á kvið og búk. Björntorp og fleiri hafa sett fram þá tilgátu að vægari en langvarandi streituviðbrögð geti ýtt undir sama mynstur.", "refs": ["Björntorp, Obes Rev 2001"]}, {"layout": "bullets", "title": "Streita, blóðsykur og insúlín", "body": "Kortisól og adrenalín hækka blóðsykur. Það er gagnlegt til skamms tíma en síður þegar það gerist dag eftir dag.", "items": ["Langvarandi hækkun kortisóls getur dregið úr næmi frumna fyrir insúlíni (insúlínviðnám).", "Innri kviðfita tengist einnig insúlínviðnámi.", "Stórar rannsóknir tengja langvarandi sálræna streitu við aukna hættu á sykursýki af tegund 2.", "Streita hefur líka áhrif á svefn, mataræði og hreyfingu, sem skipta öll máli fyrir blóðsykur."], "refs": ["Hackett og Steptoe, Nat Rev Endocrinol 2017"]}, {"layout": "text", "title": "Hvað með vöðvana?", "body": "Oft er sagt að streita „brenni vöðvum“. Það er rétt að kortisól og skyld hormón (sykursterar) brjóta niður prótein í vöðvum. Skýr vöðvarýrnun sést þó fyrst og fremst þegar magnið er mjög hátt í langan tíma, til dæmis við Cushing-heilkenni eða langvarandi steralyfjameðferð.\n\nEkki hefur verið sýnt fram á að hversdagsleg streita ein og sér rýri vöðva. Hún getur þó haft óbein áhrif, því að undir álagi sofum við verr, æfum sjaldnar og borðum óreglulegar.", "refs": ["Schakman o.fl., Int J Biochem Cell Biol 2013"]}, {"layout": "bullets", "title": "Óbeinu leiðirnar: svefn, matur og hreyfing", "body": "Líklega hefur streita mest áhrif á kviðfitu í gegnum daglegar venjur.", "items": ["Streita tengist meiri löngun í orkuríkan „huggunarmat“ hjá mörgum, en minni matarlyst hjá öðrum.", "Í tilraun þar sem svefn var skertur í 4 klst. á nótt í 2 vikur borðuðu þátttakendur meira.", "Í sömu tilraun jókst fita í kviðarholi, þar á meðal innri kviðfita.", "Undir álagi sleppum við oft hreyfingu og drekkum jafnvel meira áfengi.", "Þessar venjur hafa sjálfstæð áhrif á kviðfitu, óháð kortisóli."], "refs": ["Adam og Epel, Physiol Behav 2007", "Torres og Nowson, Nutrition 2007", "Covassin o.fl., J Am Coll Cardiol 2022"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Þegar horft er á heildarmyndina er niðurstaðan blæbrigðaríkari en fyrirsagnir gefa til kynna.", "items": ["Safngreining á 14 ferilhópum: streita tengdist aukinni fitusöfnun, en áhrifin voru mjög lítil.", "Tengslin voru sterkari hjá körlum og þegar fylgst var lengur með fólki.", "Safngreining á 15 rannsóknum: þolþjálfun minnkaði innri kviðfitu, jafnvel án megrunar.", "Mesti ávinningurinn sást við þolþjálfun af miðlungsmikilli eða mikilli ákefð."], "refs": ["Wardle o.fl., Obesity 2011", "Vissers o.fl., PLoS One 2013"]}, {"layout": "text", "title": "Er streitulosun „aðferð númer eitt“?", "body": "Stundum heyrist að streitulosun sé besta leiðin til að losna við innri kviðfitu. Rannsóknir styðja það ekki. Sterkustu gögnin varðandi innri kviðfitu snúa að hreyfingu, mataræði og svefni.\n\nStreita er hins vegar mikilvægur þáttur sem oft gleymist, því hún hefur áhrif á allt hitt: hvernig við sofum, hvað við borðum og hvort við hreyfum okkur. Streitulosun er því góður grunnur sem gerir aðrar breytingar auðveldari.", "refs": ["Wardle o.fl., Obesity 2011", "Vissers o.fl., PLoS One 2013"]}, {"layout": "bullets", "title": "Hagnýt skref", "body": "Veldu eitt eða tvö atriði til að byrja með. Litlar, stöðugar breytingar skila meiru en stórar sem endast ekki.", "items": ["Verndaðu svefninn: reglulegur háttatími og 7–9 klst. svefntækifæri.", "Hreyfðu þig daglega; þolþjálfun sem hækkar púlsinn tengist minni innri kviðfitu.", "Borðaðu reglulegar máltíðir með próteini svo streitan stýri síður matarvalinu.", "Taktu stuttar streituhlé yfir daginn, til dæmis hæga öndun í tvær mínútur.", "Fylgstu með áfengisneyslu, sérstaklega á álagstímum.", "Taktu eftir hvað kveikir á streitunni – það er fyrsta skrefið til að breyta því."]}, {"layout": "tip", "title": "Prófaðu þetta í eina viku", "body": "Skrifaðu á hverju kvöldi þrjár stuttar línur:\n\n1. Streitan í dag á skalanum 1–10.\n2. Hversu vel svafstu síðustu nótt?\n3. Borðaðirðu eða drakkstu eitthvað „út af streitu“?\n\nEftir viku sérðu oft mynstur, til dæmis að slæmur svefn og mikil streita fara saman. Þá veistu hvar best er að byrja."}, {"layout": "text", "title": "Hvenær er rétt að leita aðstoðar?", "body": "Það er eðlilegt að finna fyrir streitu. Ef þú hefur þó í meira en tvær vikur fundið fyrir viðvarandi depurð, kvíða, svefnleysi eða áhugaleysi er skynsamlegt að ræða við fagaðila.\n\nHeilsugæslan er góður fyrsti viðkomustaður og ráðgjöf fæst allan sólarhringinn í síma 1700 eða á netspjalli Heilsuveru. Hjálparsími Rauða krossins, 1717, er opinn allan sólarhringinn. Í bráðatilvikum skaltu hringja í 112."}, {"layout": "sources", "title": "Heimildir", "body": "Heimildir sem vitnað er í í þessum fyrirlestri.", "items": ["McEwen BS (1998). Protective and damaging effects of stress mediators. New England Journal of Medicine, 338(3), 171–179. doi:10.1056/NEJM199801153380307 / PMID 9428819", "Epel ES, McEwen B, Seeman T, Matthews K, Castellazzo G, Brownell KD, o.fl. (2000). Stress and body shape: stress-induced cortisol secretion is consistently greater among women with central fat. Psychosomatic Medicine, 62(5), 623–632. doi:10.1097/00006842-200009000-00005 / PMID 11020091", "Björntorp P (2001). Do stress reactions cause abdominal obesity and comorbidities? Obesity Reviews, 2(2), 73–86. doi:10.1046/j.1467-789x.2001.00027.x / PMID 12119665", "Hackett RA, Steptoe A (2017). Type 2 diabetes mellitus and psychological stress – a modifiable risk factor. Nature Reviews Endocrinology, 13(9), 547–560. doi:10.1038/nrendo.2017.64 / PMID 28664919", "Schakman O, Kalista S, Barbé C, Loumaye A, Thissen JP (2013). Glucocorticoid-induced skeletal muscle atrophy. International Journal of Biochemistry & Cell Biology, 45(10), 2163–2172. doi:10.1016/j.biocel.2013.05.036 / PMID 23806868", "Adam TC, Epel ES (2007). Stress, eating and the reward system. Physiology & Behavior, 91(4), 449–458. doi:10.1016/j.physbeh.2007.04.011 / PMID 17543357", "Torres SJ, Nowson CA (2007). Relationship between stress, eating behavior, and obesity. Nutrition, 23(11–12), 887–894. doi:10.1016/j.nut.2007.08.008 / PMID 17869482", "Covassin N, Singh P, McCrady-Spitzer SK, St Louis EK, Calvin AD, Levine JA, o.fl. (2022). Effects of experimental sleep restriction on energy intake, energy expenditure, and visceral obesity. Journal of the American College of Cardiology, 79(13), 1254–1265. doi:10.1016/j.jacc.2022.01.038 / PMID 35361348", "Wardle J, Chida Y, Gibson EL, Whitaker KL, Steptoe A (2011). Stress and adiposity: a meta-analysis of longitudinal studies. Obesity, 19(4), 771–778. doi:10.1038/oby.2010.241 / PMID 20948519", "Vissers D, Hens W, Taeymans J, Baeyens JP, Poortmans J, Van Gaal L (2013). The effect of exercise on visceral adipose tissue in overweight adults: a systematic review and meta-analysis. PLoS One, 8(2), e56415. doi:10.1371/journal.pone.0056415 / PMID 23409182"]}]'::jsonb, 18, 'mental', false, 41, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('andleg-ondun-og-hugleidsla', 'Verkfæri í dag: öndun og hugleiðsla', 'Einfaldar æfingar sem taka nokkrar mínútur á dag – og hvað má raunhæft búast við', 'slides', '[{"layout": "stat", "title": "Fimm mínútur á dag", "body": "Í slembiraðaðri rannsókn við Stanford-háskóla gerðu þátttakendur fimm mínútna öndunaræfingu eða hugleiðslu daglega í mánuð. Öndunaræfingarnar, einkum öndun með löngum útöndunum („andvarpsöndun“), bættu skapið meira en hugleiðslan.\n\nVerkfærin í þessum fyrirlestri eru ókeypis, taka stuttan tíma og hægt er að byrja í dag.", "stat": "5 mín.", "caption": "daglegar öndunaræfingar í einn mánuð tengdust betra skapi", "refs": ["Balban o.fl., Cell Rep Med 2023"]}, {"layout": "text", "title": "Af hverju skiptir öndunin máli?", "body": "Öndun er eitt fárra ósjálfráðra kerfa líkamans sem við getum líka stjórnað meðvitað. Hjartslátturinn fylgir önduninni: hann hraðar á sér við innöndun og hægir á sér við útöndun.\n\nÞegar við öndum hægt og lengjum útöndunina virkjum við sefkerfið, „hvíldarkerfi“ líkamans, meðal annars í gegnum flökkutaugina. Rannsóknir benda til að hæg öndun, um sex andardrættir á mínútu, tengist meiri ró og minni spennu.", "refs": ["Zaccaro o.fl., Front Hum Neurosci 2018"]}, {"layout": "bullets", "title": "Hæg öndun: svona gerir þú", "body": "Góð byrjunaræfing sem hentar hvar sem er – við skrifborðið, í bílnum (kyrrstæðum) eða fyrir svefninn.", "items": ["Sestu eða leggstu þægilega og slakaðu á öxlunum.", "Andaðu inn um nefið í um 4 sekúndur og leyfðu kviðnum að lyftast.", "Andaðu rólega út í um 6 sekúndur.", "Endurtaktu í 3–5 mínútur, um sex andardrætti á mínútu.", "Ef þú svimar skaltu hætta og anda eðlilega."]}, {"layout": "bullets", "title": "Kassaöndun og andvarpsöndun", "body": "Tvær aðferðir sem voru prófaðar í Stanford-rannsókninni. Prófaðu báðar og veldu þá sem þér líkar best.", "items": ["Kassaöndun: anda inn í 4 sekúndur, halda í 4, anda út í 4, halda í 4.", "Mörgum finnst kassaöndun hjálpa til að ná ró fyrir krefjandi verkefni.", "Andvarpsöndun: tvær innandanir um nefið, sú seinni stutt, svo löng útöndun um munninn.", "Í rannsókninni bætti andvarpsöndun skapið mest og hægði mest á öndunartíðni.", "Hægt er að taka eina til þrjár endurtekningar hvenær sem er yfir daginn."], "refs": ["Balban o.fl., Cell Rep Med 2023"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar um öndun?", "body": "Safngreining frá 2023 tók saman slembiraðaðar rannsóknir á öndunaræfingum.", "items": ["12 rannsóknir með 785 fullorðnum: minni upplifuð streita en í samanburðarhópum.", "Áhrifin voru lítil til miðlungsmikil (g = −0,35).", "Svipuð áhrif sáust á kvíða og depurðareinkenni.", "Flestar rannsóknirnar voru litlar og höfðu miðlungsmikla hættu á skekkju.", "Höfundar vara við því að væntingar fari fram úr gögnunum."], "refs": ["Fincham o.fl., Sci Rep 2023"]}, {"layout": "text", "title": "Hvað er núvitund?", "body": "Núvitund (e. mindfulness) snýst um að beina athyglinni að líðandi stund – andardrættinum, líkamanum, hljóðum eða hugsunum – án þess að dæma.\n\nMarkmiðið er ekki að tæma hugann. Hugurinn reikar alltaf; æfingin felst í því að taka eftir því og koma blíðlega aftur. Þekktasta námskeiðið er MBSR (e. Mindfulness-Based Stress Reduction), átta vikna námskeið með vikulegum tímum og daglegri heimaæfingu.", "refs": ["Khoury o.fl., J Psychosom Res 2015"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar um hugleiðslu?", "body": "Núvitund er ein best rannsakaða aðferðin til að draga úr streitu, en áhrifin eru hófleg.", "items": ["Goyal o.fl.: 47 rannsóknir, 3.515 þátttakendur – minni kvíði, depurð og verkir eftir 8 vikur.", "Áhrifastærðin var um 0,3–0,4 og hélst að hluta eftir 3–6 mánuði.", "Hugleiðsla reyndist ekki betri en önnur virk úrræði, svo sem hreyfing eða samtalsmeðferð.", "Galante o.fl.: 136 rannsóknir, 11.605 þátttakendur – minni kvíði, depurð og vanlíðan en hjá þeim sem gerðu ekkert.", "Áhrifin voru breytileg eftir aðstæðum og hópum."], "refs": ["Goyal o.fl., JAMA Intern Med 2014", "Galante o.fl., PLoS Med 2021"]}, {"layout": "text", "title": "Hvað þýðir „lítil til miðlungsmikil áhrif“?", "body": "Áhrifastærð segir til um hversu mikill munur er á hópum. Gróflega er 0,2 talið lítið, 0,5 miðlungsmikið og 0,8 mikið.\n\nÁhrif öndunar og núvitundar eru yfirleitt á bilinu 0,3–0,5. Það þýðir að margir finna greinanlegan mun, en ekki allir. Þetta er raunhæf mynd: gagnlegt verkfæri, en ekki töfralausn. Mestur ávinningur næst líklega með því að æfa reglulega yfir vikur.", "refs": ["Goyal o.fl., JAMA Intern Med 2014", "Khoury o.fl., J Psychosom Res 2015"]}, {"layout": "bullets", "title": "Tíu mínútna byrjendaæfing", "body": "Stilltu tímamæli á 10 mínútur. Ef það er of langt til að byrja með eru 3–5 mínútur líka fín byrjun.", "items": ["Sestu uppréttur en afslappaður og lokaðu augunum eða horfðu niður.", "Taktu eftir snertingu líkamans við stólinn og gólfið.", "Beindu athyglinni að andardrættinum, þar sem þú finnur hann best.", "Þegar hugurinn reikar skaltu merkja það („hugsun“) og snúa aftur að önduninni.", "Endaðu á að taka eftir hvernig þér líður núna, án þess að dæma."]}, {"layout": "text", "title": "Geta öpp hjálpað?", "body": "Já, að einhverju marki. Safngreining á 34 slembiröðuðum rannsóknum (7.566 þátttakendur) sýndi að núvitundaröpp tengdust minni upplifaðri streitu, kvíða og depurð, með litlum til miðlungsmiklum áhrifum.\n\nHöfundar hvetja þó til varkárni því rannsóknirnar voru misgóðar. Appið kemur ekki í stað æfingarinnar sjálfrar – það er fyrst og fremst leið til að muna eftir henni og fá leiðsögn.", "refs": ["Gál o.fl., J Affect Disord 2021"]}, {"layout": "tip", "title": "Tengdu æfinguna við venju sem þú átt fyrir", "body": "Auðveldast er að byggja nýjan vana ofan á gamlan. Dæmi:\n\n• Eftir morgunkaffið: 5 mínútna hugleiðsla.\n• Í bílnum áður en þú ferð inn eftir vinnu: 1 mínúta af andvarpsöndun.\n• Þegar þú leggst á koddann: hæg öndun þar til þú sofnar.\n\nSettu lágmarkið svo lágt að þú getir alltaf staðið við það. Ein mínúta telur."}, {"layout": "bullets", "title": "Algengar hindranir", "body": "Nánast allir lenda í þessu – það þýðir ekki að þú sért að gera eitthvað rangt.", "items": ["„Ég get ekki tæmt hugann“ – það er heldur ekki markmiðið.", "„Ég sofna“ – prófaðu að sitja í stað þess að liggja, eða æfa fyrr um daginn.", "„Ég verð órólegur“ – styttu æfinguna eða prófaðu gönguhugleiðslu.", "Stundum koma erfiðar tilfinningar upp; þá er í lagi að hætta og opna augun.", "Ef æfingar vekja ítrekað mikla vanlíðan er gott að ræða það við fagaðila."]}, {"layout": "text", "title": "Verkfæri, ekki kraftaverk", "body": "Öndun og núvitund eru ódýr og aðgengileg verkfæri sem rannsóknir benda til að geti dregið úr streitu hjá mörgum. Þau virka best sem hluti af heild, með svefni, hreyfingu og góðum tengslum við annað fólk.\n\nEf depurð, kvíði eða svefnleysi hafa varað lengur en í tvær vikur skaltu ræða við fagaðila, til dæmis á heilsugæslunni eða í síma 1700. Hjálparsími Rauða krossins, 1717, er opinn allan sólarhringinn.", "refs": ["Goyal o.fl., JAMA Intern Med 2014"]}, {"layout": "sources", "title": "Heimildir", "body": "Heimildir sem vitnað er í í þessum fyrirlestri.", "items": ["Zaccaro A, Piarulli A, Laurino M, Garbella E, Menicucci D, Neri B, o.fl. (2018). How breath-control can change your life: a systematic review on psycho-physiological correlates of slow breathing. Frontiers in Human Neuroscience, 12, 353. doi:10.3389/fnhum.2018.00353 / PMID 30245619", "Balban MY, Neri E, Kogon MM, Weed L, Nouriani B, Jo B, o.fl. (2023). Brief structured respiration practices enhance mood and reduce physiological arousal. Cell Reports Medicine, 4(1), 100895. doi:10.1016/j.xcrm.2022.100895 / PMID 36630953", "Fincham GW, Strauss C, Montero-Marin J, Cavanagh K (2023). Effect of breathwork on stress and mental health: a meta-analysis of randomised-controlled trials. Scientific Reports, 13(1), 432. doi:10.1038/s41598-022-27247-y / PMID 36624160", "Khoury B, Sharma M, Rush SE, Fournier C (2015). Mindfulness-based stress reduction for healthy individuals: a meta-analysis. Journal of Psychosomatic Research, 78(6), 519–528. doi:10.1016/j.jpsychores.2015.03.009 / PMID 25818837", "Goyal M, Singh S, Sibinga EM, Gould NF, Rowland-Seymour A, Sharma R, o.fl. (2014). Meditation programs for psychological stress and well-being: a systematic review and meta-analysis. JAMA Internal Medicine, 174(3), 357–368. doi:10.1001/jamainternmed.2013.13018 / PMID 24395196", "Galante J, Friedrich C, Dawson AF, Modrego-Alarcón M, Gebbing P, Delgado-Suárez I, o.fl. (2021). Mindfulness-based programmes for mental health promotion in adults in nonclinical settings: a systematic review and meta-analysis of randomised controlled trials. PLoS Medicine, 18(1), e1003481. doi:10.1371/journal.pmed.1003481 / PMID 33428616", "Gál É, Ștefan S, Cristea IA (2021). The efficacy of mindfulness meditation apps in enhancing users'' well-being and mental health related outcomes: a meta-analysis of randomized controlled trials. Journal of Affective Disorders, 279, 131–142. doi:10.1016/j.jad.2020.09.134 / PMID 33049431"]}]'::jsonb, 16, 'mental', false, 42, true)
