  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('andleg-felagsleg-tengsl-og-tilgangur', 'Félagsleg tengsl og tilgangur', 'Af hverju samskipti við aðra og tilgangur í lífinu skipta máli fyrir heilsuna', 'slides', '[{"layout": "stat", "title": "Tengsl og lífslíkur", "body": "Í safngreiningu á 148 rannsóknum með yfir 300.000 þátttakendum voru þeir sem höfðu sterkari félagsleg tengsl 50% líklegri til að vera á lífi við lok rannsóknartímans.\n\nHöfundarnir bentu á að þessi tengsl væru sambærileg við vel þekkta áhættuþætti á borð við reykingar og hreyfingarleysi. Rannsóknirnar sýna tengsl en sanna ekki orsakasamband.", "stat": "50%", "caption": "meiri líkur á að lifa á rannsóknartímanum með sterkari félagsleg tengsl", "refs": ["Holt-Lunstad o.fl., PLoS Med 2010"]}, {"layout": "text", "title": "Við erum félagsverur", "body": "Í gegnum þróunarsöguna var það lífsnauðsynlegt að tilheyra hópi. Heilinn bregst því við einangrun eins og hættumerki: við verðum varari um okkur, sofum léttar og streitukerfið verður virkara.\n\nNáin tengsl virka á móti sem „streitudempari“. Að hafa einhvern til að tala við, biðja um hjálp eða einfaldlega hlæja með getur gert erfiðar aðstæður viðráðanlegri."}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Tvær stórar safngreiningar Holt-Lunstad og félaga eru mest vitnað í á þessu sviði.", "items": ["2010: 148 rannsóknir, 308.849 þátttakendur – sterk tengsl tengdust betri lifun.", "Tengslin voru sterkust þegar mælt var hversu virk þátttaka fólks í samfélaginu var.", "2015: félagsleg einangrun tengdist 29% meiri líkum á dauðsfalli á rannsóknartímanum.", "Einmanaleiki tengdist 26% og að búa einn 32% meiri líkum.", "Þetta eru ferilrannsóknir; aðrir þættir geta skýrt hluta tengslanna."], "refs": ["Holt-Lunstad o.fl., PLoS Med 2010", "Holt-Lunstad o.fl., Perspect Psychol Sci 2015"]}, {"layout": "stat", "title": "Einmanaleiki á heimsvísu", "body": "Árið 2025 birti nefnd Alþjóðaheilbrigðismálastofnunarinnar (WHO) um félagsleg tengsl skýrslu um einmanaleika. Samkvæmt mati hennar finnur um einn af hverjum sex fyrir einmanaleika, og einmanaleiki tengist um 100 dauðsföllum á hverri klukkustund.\n\nWHO hvetur til þess að félagsleg tengsl verði sett í forgang í lýðheilsu, rétt eins og hreyfing og mataræði.", "stat": "871.000", "caption": "dauðsföll á ári tengjast einmanaleika samkvæmt mati WHO", "refs": ["WHO, Commission on Social Connection 2025"]}, {"layout": "text", "title": "Einmanaleiki er ekki það sama og einvera", "body": "Félagsleg einangrun er hlutlæg: fá samskipti við annað fólk. Einmanaleiki er huglægur: tilfinningin um að tengslin sem við höfum séu ekki nóg.\n\nÞví er hægt að vera einmana í fjölmenni eða í hjónabandi, og líða vel einn með sjálfum sér. Einvera getur verið nærandi. Rannsóknir benda til að bæði einangrun og einmanaleiki tengist verri heilsu, óháð hvort öðru.", "refs": ["Holt-Lunstad o.fl., Perspect Psychol Sci 2015"]}, {"layout": "bullets", "title": "Hvernig tengsl geta haft áhrif á líkamann", "body": "Vísindamenn eru enn að kortleggja leiðirnar, en nokkrar skýringar eru taldar líklegar.", "items": ["Stuðningur annarra getur mildað streituviðbrögð við áföllum og álagi.", "Fólk í kringum okkur hefur áhrif á venjur: hreyfingu, mataræði, svefn og læknisheimsóknir.", "Einangrun tengist verri svefni og meiri árvekni gagnvart hættu.", "Tengsl geta gefið lífinu merkingu og ástæðu til að hugsa um heilsuna."], "refs": ["Holt-Lunstad o.fl., PLoS Med 2010"]}, {"layout": "stat", "title": "Fjölbreytt tengsl og kvef", "body": "Í frægri tilraun fengu 276 heilbrigðir sjálfboðaliðar kvefveiru í nefið. Þeir sem höfðu fjölbreyttust félagsleg tengsl (til dæmis maki, vinir, vinnufélagar og félagsstarf) fengu síður kvef. Hættan minnkaði í réttu hlutfalli við fjölbreytni tengslanna.\n\nMunurinn skýrðist aðeins að hluta af reykingum, svefni og öðrum þáttum.", "stat": "4,2", "caption": "sinnum meiri líkur á kvefi hjá þeim sem höfðu fæstar tegundir tengsla", "refs": ["Cohen o.fl., JAMA 1997"]}, {"layout": "bullets", "title": "Tilgangur í lífinu", "body": "Tilgangur er tilfinningin um að lífið hafi stefnu og að það sem við gerum skipti máli.", "items": ["Safngreining á 10 rannsóknum (136.265 manns): meiri tilgangur tengdist 17% lægri dánartíðni.", "Sama safngreining: 17% færri hjarta- og æðaáföll hjá þeim sem höfðu meiri tilgang.", "Bandarísk rannsókn á 6.985 manns yfir fimmtugu sýndi svipuð tengsl.", "Tilgangur gæti tengst heilsu í gegnum betri venjur og minna streituálag.", "Þetta eru ferilrannsóknir og sanna ekki orsakasamband."], "refs": ["Cohen o.fl., Psychosom Med 2016", "Alimujiang o.fl., JAMA Netw Open 2019"]}, {"layout": "bullets", "title": "Hvernig finnur maður tilgang?", "body": "Tilgangur þarf ekki að vera stór eða háleitur. Hann byggist oft á mörgum litlum hlutum.", "items": ["Spurðu þig: hvað skiptir mig mestu máli og hvar vil ég leggja af mörkum?", "Hlutverk gefa tilgang: foreldri, afi eða amma, vinur, liðsfélagi, samstarfsmaður.", "Lærðu eitthvað nýtt, til dæmis hljóðfæri, tungumál eða handverk.", "Hjálpaðu öðrum – sjálfboðastarf sameinar tengsl og tilgang.", "Tilgangur breytist yfir ævina, til dæmis við starfslok; þá er gott að leita hans á ný."]}, {"layout": "stat", "title": "Vinátta tekur tíma", "body": "Rannsókn Jeffreys Hall skoðaði hve margar klukkustundir fólk þurfti að eyða saman til að kynni yrðu að vináttu. Það tók að jafnaði um 50 klukkustundir að verða kunningjar, um 90 að verða vinir og yfir 200 að verða nánir vinir.\n\nSameiginlegar frístundir skiptu meira máli en tími saman í vinnu. Vinátta byggist á endurteknum samverustundum.", "stat": "200+", "caption": "klukkustundir saman þarf að jafnaði til að verða nánir vinir", "refs": ["Hall, J Soc Pers Relat 2019"]}, {"layout": "bullets", "title": "Hagnýtar leiðir til að tengjast", "body": "WHO bendir á einföld skref sem allir geta tekið.", "items": ["Hafðu samband við vin sem þú hefur ekki heyrt í lengi.", "Leggðu símann frá þér og vertu til staðar í samtalinu.", "Heilsaðu nágrönnum og spjallaðu við fólk sem þú hittir reglulega.", "Taktu þátt í reglulegu starfi: kór, gönguhópi, íþróttafélagi eða leshring.", "Bjóddu fram krafta þína í sjálfboðastarfi.", "Segðu oftar „já“ við boðum, jafnvel þegar sófinn freistar."], "refs": ["WHO, Commission on Social Connection 2025"]}, {"layout": "tip", "title": "Tengslaáætlun vikunnar", "body": "Skrifaðu niður nöfn þriggja manneskja sem skipta þig máli.\n\n• Hringdu í eina þeirra í vikunni – símtal frekar en skilaboð.\n• Bókaðu samverustund með annarri: göngu, kaffi eða máltíð.\n• Gerðu eitt nýtt sem gæti leitt til nýrra kynna.\n\nEndurtaktu í hverri viku. Reglulegar samverustundir byggja upp tengsl smám saman."}, {"layout": "text", "title": "Þegar einmanaleikinn er þungur", "body": "Einmanaleiki getur verið sár og það getur verið erfitt að taka fyrsta skrefið. Þú ert ekki einn um að líða svona.\n\nHjálparsími Rauða krossins, 1717, er opinn allan sólarhringinn, bæði í síma og á netspjalli. Ef einmanaleikanum fylgir viðvarandi depurð eða kvíði í meira en tvær vikur er skynsamlegt að ræða við fagaðila, til dæmis á heilsugæslunni eða í síma 1700."}, {"layout": "sources", "title": "Heimildir", "body": "Heimildir sem vitnað er í í þessum fyrirlestri.", "items": ["Holt-Lunstad J, Smith TB, Layton JB (2010). Social relationships and mortality risk: a meta-analytic review. PLoS Medicine, 7(7), e1000316. doi:10.1371/journal.pmed.1000316 / PMID 20668659", "Holt-Lunstad J, Smith TB, Baker M, Harris T, Stephenson D (2015). Loneliness and social isolation as risk factors for mortality: a meta-analytic review. Perspectives on Psychological Science, 10(2), 227–237. doi:10.1177/1745691614568352 / PMID 25910392", "World Health Organization (2025). From loneliness to social connection: charting a path to healthier societies. Report of the WHO Commission on Social Connection. Genf: WHO. ISBN 978-92-4-011236-0", "Cohen S, Doyle WJ, Skoner DP, Rabin BS, Gwaltney JM Jr (1997). Social ties and susceptibility to the common cold. JAMA, 277(24), 1940–1944. doi:10.1001/jama.1997.03540480040036 / PMID 9200634", "Cohen R, Bavishi C, Rozanski A (2016). Purpose in life and its relationship to all-cause mortality and cardiovascular events: a meta-analysis. Psychosomatic Medicine, 78(2), 122–133. doi:10.1097/PSY.0000000000000274 / PMID 26630073", "Alimujiang A, Wiensch A, Boss J, Fleischer NL, Mondul AM, McLean K, o.fl. (2019). Association between life purpose and mortality among US adults older than 50 years. JAMA Network Open, 2(5), e194270. doi:10.1001/jamanetworkopen.2019.4270 / PMID 31125099", "Hall JA (2019). How many hours does it take to make a friend? Journal of Social and Personal Relationships, 36(4), 1278–1296. doi:10.1177/0265407518761225"]}]'::jsonb, 16, 'mental', false, 43, true)
