  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('andleg-ad-gefa-af-ser-og-faekka-streituvoldum', 'Að gefa af sér og fækka streituvöldum', 'Gjafmildi, mörk og langtímalausnir á álagi – og hvenær á að leita aðstoðar', 'slides', '[{"layout": "text", "title": "Tvær hliðar á sama peningi", "body": "Þegar við hugsum um streitu hugsum við oft um að taka eitthvað burt: minna álag, færri verkefni. Það skiptir miklu máli og við skoðum það hér.\n\nEn rannsóknir benda líka til að það að bæta einhverju við – að gefa af sér, hjálpa öðrum og vera hluti af einhverju stærra – geti bætt líðan. Í þessum fyrirlestri skoðum við báðar hliðarnar."}, {"layout": "stat", "title": "Að eyða peningum í aðra", "body": "Í þekktri tilraun fengu þátttakendur umslag með lágri peningaupphæð. Helmingurinn átti að eyða henni í sjálfan sig og hinn helmingurinn í aðra, til dæmis gjöf eða framlag til góðgerðamála.\n\nÍ lok dags sögðust þeir sem eyddu peningunum í aðra vera ánægðari. Síðari rannsóknir í 136 löndum sýndu svipuð tengsl, bæði í ríkum og fátækum löndum.", "stat": "136", "caption": "lönd þar sem gjafmildi tengdist meiri hamingju", "refs": ["Dunn o.fl., Science 2008", "Aknin o.fl., J Pers Soc Psychol 2013"]}, {"layout": "bullets", "title": "Hvað segja rannsóknirnar?", "body": "Góðvild virðist bæta líðan þess sem gefur, en áhrifin eru hófleg.", "items": ["Safngreining á tilraunum um góðverk (4.045 þátttakendur): lítil til miðlungsmikil bæting á líðan.", "Stórar endurtekningarrannsóknir staðfestu að gjafmildi getur aukið hamingju.", "Í sömu endurtekningum voru áhrifin minni og háðari aðferðum en í fyrstu rannsóknunum.", "Heiðarleg niðurstaða: að gefa af sér er gott fyrir flesta, en engin töfralausn."], "refs": ["Curry o.fl., J Exp Soc Psychol 2018", "Aknin o.fl., J Pers Soc Psychol 2020"]}, {"layout": "bullets", "title": "Sjálfboðastarf og heilsa", "body": "Sjálfboðastarf sameinar að gefa af sér, tengsl við aðra og tilgang.", "items": ["Safngreining á eldra fólki (55+): sjálfboðaliðar voru 24% ólíklegri til að deyja á rannsóknartímanum.", "Sú tala er eftir leiðréttingu fyrir heilsu og öðrum þáttum.", "Í ferilrannsóknum tengdist sjálfboðastarf minni depurð og meiri lífsánægju.", "Slembiraðaðar tilraunir hafa ekki staðfest þessi áhrif með skýrum hætti.", "Hluti skýringarinnar getur verið að hraustara fólk bjóði sig frekar fram."], "refs": ["Okun o.fl., Psychol Aging 2013", "Jenkinson o.fl., BMC Public Health 2013"]}, {"layout": "bullets", "title": "Hugmyndir að því að gefa af sér", "body": "Það þarf hvorki mikla peninga né mikinn tíma. Veldu það sem hentar þér.", "items": ["Lítil góðverk: bjóða aðstoð, hrósa, halda hurðinni opinni, senda þakkarskilaboð.", "Gefðu tíma: heimsæktu einhvern sem er mikið einn eða hjálpaðu við flutninga.", "Sjálfboðastarf hjá Rauða krossinum, íþróttafélagi, skátum eða í hverfinu.", "Deildu hæfni þinni: kenndu, leiðbeindu eða aðstoðaðu við verkefni.", "Hlustaðu af athygli – það er oft dýrmætasta gjöfin."]}, {"layout": "tip", "title": "Góðverkadagur", "body": "Veldu einn dag í vikunni og reyndu að gera fimm lítil góðverk þann dag. Skrifaðu þau niður um kvöldið og taktu eftir hvernig þér líður.\n\nÞað skiptir máli að gera þetta af fúsum og frjálsum vilja. Góðvild á ekki að verða enn eitt verkefnið á listanum – ef hún veldur álagi, minnkaðu hana."}, {"layout": "text", "title": "Kortleggðu streituvaldana", "body": "Skammtímaaðferðir eins og öndun hjálpa, en ef sami streituvaldurinn heldur áfram mánuðum saman þarf líka að skoða rótina.\n\nTaktu blað og skrifaðu niður allt sem veldur þér streitu um þessar mundir: vinna, fjármál, samskipti, heimilið, heilsa, fréttir og samfélagsmiðlar. Það eitt að sjá listann á blaði gerir hann oft viðráðanlegri."}, {"layout": "bullets", "title": "Hringirnir þrír", "body": "Flokkaðu hvern streituvald eftir því hversu mikil áhrif þú hefur á hann.", "items": ["Það sem ég stjórna: skipuleggðu og taktu fyrsta litla skrefið í vikunni.", "Það sem ég hef áhrif á: ræddu málin, semdu eða biddu um aðstoð.", "Það sem ég get ekki breytt: æfðu að sætta þig við það og beindu orkunni annað.", "Dragðu úr óþarfa áreiti, svo sem fréttum og tilkynningum, sem þú stjórnar sjálfur.", "Veldu einn streituvald í einu – ekki alla í einu."]}, {"layout": "stat", "title": "Langir vinnudagar", "body": "Í safngreiningu á gögnum yfir 500.000 manns tengdist 55 klukkustunda vinnuvika eða lengri 33% meiri hættu á heilablóðfalli en hefðbundin 35–40 stunda vika. Tengslin við kransæðasjúkdóm voru veikari.\n\nWHO og Alþjóðavinnumálastofnunin mátu að langur vinnutími hefði tengst um 745.000 dauðsföllum af völdum hjartasjúkdóma og heilablóðfalla árið 2016.", "stat": "33%", "caption": "meiri hætta á heilablóðfalli við 55+ vinnustundir á viku", "refs": ["Kivimäki o.fl., Lancet 2015", "Pega o.fl., Environ Int 2021"]}, {"layout": "bullets", "title": "Mörk í vinnunni", "body": "Mörk eru ekki leti; þau gera okkur kleift að skila góðu starfi til lengri tíma.", "items": ["Ákveddu hvenær vinnudeginum lýkur og hafðu lítinn lokasið, til dæmis verkefnalista fyrir morgundaginn.", "Slökktu á vinnutilkynningum utan vinnutíma ef starfið leyfir.", "Segðu „nei“ eða „ekki núna“ og bjóddu annan kost: „Ég get þetta á fimmtudaginn.“", "Ræddu við yfirmann um forgangsröðun þegar verkefnin eru of mörg.", "Taktu stutt hlé yfir daginn og nýttu sumarfríið.", "WHO mælir með að stjórnendur fái þjálfun í að draga úr streitu á vinnustað."], "refs": ["WHO, Guidelines on mental health at work 2022"]}, {"layout": "text", "title": "Að aftengjast eftir vinnu", "body": "Það skiptir ekki bara máli hve lengi við vinnum heldur hvort við náum að kúpla okkur frá vinnunni í frítímanum. Rannsóknir Sonnentag og félaga benda til að fólk sem nær að aftengjast andlega eftir vinnu finni fyrir minni þreytu og meiri vellíðan.\n\nAthafnir sem krefjast fullrar athygli, eins og hreyfing, tónlist, útivera og samvera með öðrum, auðvelda mörgum að skipta um gír.", "refs": ["Sonnentag, Curr Dir Psychol Sci 2012"]}, {"layout": "bullets", "title": "Merki um að álagið sé orðið of mikið", "body": "Ef nokkur þessara einkenna hafa varað lengur en í tvær vikur er tími til að staldra við og tala við einhvern.", "items": ["Viðvarandi þreyta sem lagast ekki við hvíld eða frí.", "Svefnvandi: erfitt að sofna, vakna oft eða vakna mjög snemma.", "Depurð, áhugaleysi eða gleðileysi.", "Kvíði, pirringur eða erfiðleikar með einbeitingu.", "Líkamleg einkenni eins og höfuðverkur, magaverkir eða hjartsláttur.", "Meiri notkun áfengis eða annarra efna til að ná sér niður."]}, {"layout": "bullets", "title": "Hvert get ég leitað?", "body": "Það er styrkleiki að biðja um aðstoð. Hér eru nokkrir staðir til að byrja.", "items": ["Heilsugæslan: heimilislæknir og sálfræðiþjónusta heilsugæslunnar.", "Sími 1700 og netspjall Heilsuveru: ráðgjöf hjúkrunarfræðinga allan sólarhringinn.", "Hjálparsími Rauða krossins, 1717: opinn allan sólarhringinn í síma og á netspjalli.", "Píeta-samtökin, 552 2218: stuðningur allan sólarhringinn vegna sjálfsvígshugsana.", "Sálfræðingar á stofu; mörg stéttarfélög styrkja slíka þjónustu.", "Í bráðatilvikum: hringdu í 112."]}, {"layout": "text", "title": "Samantekt", "body": "Að gefa af sér, hvort sem er með tíma, athygli eða litlum góðverkum, getur bætt líðan og styrkt tengsl við aðra. Áhrifin eru hófleg en raunveruleg.\n\nTil lengri tíma skiptir líka máli að fækka streituvöldum: kortleggja þá, setja mörk í vinnu og ná að aftengjast. Og ef vanlíðan varir í meira en tvær vikur er alltaf rétt að ræða við fagaðila."}, {"layout": "sources", "title": "Heimildir", "body": "Heimildir sem vitnað er í í þessum fyrirlestri.", "items": ["Dunn EW, Aknin LB, Norton MI (2008). Spending money on others promotes happiness. Science, 319(5870), 1687–1688. doi:10.1126/science.1150952 / PMID 18356530", "Aknin LB, Barrington-Leigh CP, Dunn EW, Helliwell JF, Burns J, Biswas-Diener R, o.fl. (2013). Prosocial spending and well-being: cross-cultural evidence for a psychological universal. Journal of Personality and Social Psychology, 104(4), 635–652. doi:10.1037/a0031578 / PMID 23421360", "Curry OS, Rowland LA, Van Lissa CJ, Zlotowitz S, McAlaney J, Whitehouse H (2018). Happy to help? A systematic review and meta-analysis of the effects of performing acts of kindness on the well-being of the actor. Journal of Experimental Social Psychology, 76, 320–329. doi:10.1016/j.jesp.2018.02.014", "Aknin LB, Dunn EW, Proulx J, Lok I, Norton MI (2020). Does spending money on others promote happiness?: A registered replication report. Journal of Personality and Social Psychology, 119(2), e15–e26. doi:10.1037/pspa0000191 / PMID 32250135", "Okun MA, Yeung EW, Brown S (2013). Volunteering by older adults and risk of mortality: a meta-analysis. Psychology and Aging, 28(2), 564–577. doi:10.1037/a0031519 / PMID 23421326", "Jenkinson CE, Dickens AP, Jones K, Thompson-Coon J, Taylor RS, Rogers M, o.fl. (2013). Is volunteering a public health intervention? A systematic review and meta-analysis of the health and survival of volunteers. BMC Public Health, 13, 773. doi:10.1186/1471-2458-13-773 / PMID 23968220", "Kivimäki M, Jokela M, Nyberg ST, Singh-Manoux A, Fransson EI, Alfredsson L, o.fl. (2015). Long working hours and risk of coronary heart disease and stroke: a systematic review and meta-analysis of published and unpublished data for 603,838 individuals. Lancet, 386(10005), 1739–1746. doi:10.1016/S0140-6736(15)60295-1 / PMID 26298822", "Pega F, Náfrádi B, Momen NC, Ujita Y, Streicher KN, Prüss-Üstün AM, o.fl. (2021). Global, regional, and national burdens of ischemic heart disease and stroke attributable to exposure to long working hours for 194 countries, 2000–2016: a systematic analysis from the WHO/ILO Joint Estimates of the Work-related Burden of Disease and Injury. Environment International, 154, 106595. doi:10.1016/j.envint.2021.106595 / PMID 34011457", "World Health Organization (2022). WHO guidelines on mental health at work. Genf: WHO. ISBN 978-92-4-005305-2", "Sonnentag S (2012). Psychological detachment from work during leisure time: the benefits of mentally disengaging from work. Current Directions in Psychological Science, 21(2), 114–118. doi:10.1177/0963721411434979"]}]'::jsonb, 18, 'mental', false, 44, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind, slides = excluded.slides,
  duration_min = excluded.duration_min, pillar = excluded.pillar, sort = excluded.sort, published = excluded.published;

-- The HIIT + strength program comes with the exercise lectures and the
-- visceral-fat core of each other pillar.
update public.hc_plan_templates set lecture_slugs = array['innri-kvidfita', 'hreyfing-ad-byrja-rett', 'hreyfing-styrktarthjalfun-verdmaetasti-vefurinn', 'hreyfing-hiit-stutt-og-akaft', 'svefn-forsenda-alls-annars', 'naering-sykur-insulin-kvidfita', 'andleg-streita-kortisol-kvidfita']
where key = 'hiit-styrkur';
